quests[30960] = { id = 30960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning from the Pass", description = "I still have some cleanup to do here in the pass - there are some mantid still making it through. You're a valuable person to have at hand though, and I know Taran wouldn't appreciate me keeping you longer for such basic work.\n\nTaran should still be in the main camp with Gao-Ran. Report back in. I'll catch up with you a bit later.", sourceObjective = "Report in to Taran Zhu at the Gao-Ran Battlefront.", completion = "Welcome back. I heard about the breaches in the eastern pass. It sounds like I put the right people on the job.", sourceObjectiveStatus = "unverified-source-field" }
quests[30961] = { id = 30961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Savior of the Inkgill", description = "I will go now to return to my kinsmen. Please visit us back at the southwestern edge of the Mere, so that we may thank you.", sourceObjective = "Speak with Waterspeaker Gorai at the southwestern edge of Jinyu Mere.", sourceObjectiveStatus = "unverified-source-field" }
quests[30963] = { id = 30963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Field Armorer", description = "The Shado-Pan fight. As such, their armor often gets cut, scratched, torn, and burned. And it's my job to repair it.\n\nI'm no armorer, but I can repair a broken piece of mail as long as the hole's not too big.\n\nI prefer to use shell fragments from the tortoises that live in the wild fields to the northeast. Get some for me, and I can keep more Shado-Pan armored and alive.", sourceObjective = "Obtain 120 Rankbite Shell Fragments.", progress = "I refuse to let one of our kind fall just because of a broken set of armor.", completion = "Excellent. I'll get to repairing the armor tonight, once most everyone's returned.", sourceObjectiveStatus = "unverified-source-field" }
quests[30964] = { id = 30964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Poultice", description = "A dry bandage doesn't do much good, other than maybe keeping bugs out of the wound. In some camps, that's the best you can hope for.\n\nNot in my camp, though.\n\nI prefer to make a paste from whatever soothing herbs I can find, and layer that between bandages. The most soothing herbs I've been able to find in the field are the Mao-Willows from the fields in the northeast. If you run into any, bring them back.", sourceObjective = "Obtain 11 Mao-Willows.", progress = "Any luck out there, {name}?", completion = "These will do.\n\nThe Shado-Pan appreciates your work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30967] = { id = 30967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free the Dissenters", description = "Not all of my fellow villagers from Inkgill are corrupted. Many heeded my warnings and did not drink of the sha-tainted waters.\n\nThey are in hiding, terrified, and intimidated by the guards.\n\nPlease, tell them there is hope! Go into the village to the north. Speak with them and send them to me.", sourceObjective = "Rescue 6 Inkgill Dissenters in Inkgill Mere.", completion = "Though we may not seem like much, from these inauspicious beginnings I know we will rebuild. Thank you, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[30968] = { id = 30968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sha of Hatred", description = "The end of our hunt is upon us. We have gathered the strongest the Shado-Pan have to offer, and with your strength to aid us, we will defeat the Sha of Hatred and choke out its influence on the world.\n\nWhen we enter the tunnel, stay close, and keep hatred clear from your heart. The fight ahead will put all of us to the test.\n\nWhatever happens, it has been an honor traveling beside you, {name}.", sourceObjective = "Defeat the Sha of Hatred.", completion = "Defeating a Sha... is not an easy thing. It is a miracle that we came out of this unscathed.\n\nTaran still blames himself for letting his hatred get the best of him and setting this beast loose upon the land. It may take some time for him to come to terms with this, but it is important that he does, lest he be vulnerable again.\n\nWe accomplished a great thing this day, a thing that will not soon be forgotten.\n\nAnd neither shall you for your hand in this.  Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30969] = { id = 30969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Enemy", description = "The power of these Dark Shaman has attracted many allies, {name}. Former members of the Horde that now work towards some dark purpose.\n\nWe need to make an example of them before we have another twilight's hammer on our hands.\n\nKill any cultist you come across and bring me their insignia.", sourceObjective = "Collect 5 Corrupted Insignia from any cultist in Ragefire Chasm.", progress = "Have you collected the insignia?", completion = "Good work, {name}. This will make it very clear how Garrosh is going to deal with failures...", sourceObjectiveStatus = "unverified-source-field" }
quests[30970] = { id = 30970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enraged By Hatred", description = "These scorpions are infected with sha. It seems to have driven them out of their hole and into our camp, seething with hatred at invaders in their territory.\n\nWe need to clear the scorpions and secure the camp. Kill any you find.", sourceObjective = "Kill 9 Seething Fleshrippers.", progress = "The Sha of Hatred's passing did this to them. I doubt this is the only thing that will have been affected by its passing.", completion = "Good. What's left of the camp will be a bit safer.", sourceObjectiveStatus = "unverified-source-field" }
quests[30971] = { id = 30971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Stock", description = "I was dispatched back to camp to gather pitch-tipped arrows for our archers at the bridge, and this is what I came to. I trained with most of these pandaren... I wasn't prepared for this.\n\nStill, the archers at the bridge need our help. If you could help gather arrows from the wreckage, then maybe we can salvage something from this horror.", sourceObjective = "Gather 120 Shado-Pan Fire Arrows.", progress = "The pandaren at the bridge are depending on us...", completion = "I... you... er, thank you. You didn't have to help, but you did. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30972] = { id = 30972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Fight", description = "Lao-Chin's archers will need these arrows down at the bridge. Can you bring them?", sourceObjective = "Bring the Quiver of Shado-Pan Fire Arrows to Lao-Chin the Iron Belly at Dusklight Bridge.", progress = "Welcome to the mess.", completion = "Taran Zhu told me what became of my camp. I would have stopped it if I could, but the attacks from the bridge have not let up.\n\nThank you for bringing these arrows - my archers will make good use of them.", sourceObjectiveStatus = "unverified-source-field" }
quests[30973] = { id = 30973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up In Flames", description = "The mantid coming across the bridge have thick carapaces that shrug off most of our attacks. They have a weakness though: fire.\n\nLao-Chen's men brought kegs to the battlefield for exactly this purpose.  Kick the kegs into groups of mantid, and Lao-Chin's archers will light them up.\n\nThey should be easy to finish off from there.", sourceObjective = "Kill 10 Kor'thik Timberhusks with the aid of Lao-Chin's kegs.", progress = "Creative solution.  Lao-Chin impresses.", completion = "We have the added benefit that the mantid will leave with broken morale after watching their brethren burn to death.  Grim, but many lives will be spared if they simply stop pressing our lines.", sourceObjectiveStatus = "unverified-source-field" }
quests[30974] = { id = 30974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raising Spirits", description = "The kegs are full of my worst stock. Good for burning, crap for drinking.\n\nI've broken out some tankards of my best spirits and had them carried out amongst the kegs though - those are for my well-deserving men!  Spirits to raise their spirits after endless, grueling fighting.\n\nWould you be up for spreading the good cheer?", sourceObjective = "Throw 8 Iron Belly Spirits to nearby Dusklight Skirmishers and Dusklight Rangers.", sourceObjectiveStatus = "unverified-source-field" }
quests[30975] = { id = 30975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Taking of Dusklight Bridge", description = "Let's press these insects back across the bridge and break their spirits!\n\nFollow my lead.", sourceObjective = "Help Lao-Chin the Iron Belly hold the far side of the Dusklight Bridge.", completion = "The mantid aren't likely to return soon after a beating like that... and now Lao-Chin is free to join us in the hunt.", sourceObjectiveStatus = "unverified-source-field" }
quests[30976] = { id = 30976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Hunt", description = "We are one stronger. Your help is invaluable.\n\nLet's move on westward to Rensai's Watchpost to find the last member for our party.", sourceObjective = "Ride with Taran Zhu, Taoshi, and Lao-Chin to Rensai's Watchpost.", completion = "We are close. I can feel the unnatural hatred surging.\n\nIt's a testament to the training of the Shado-Pan that the forces here have not been consumed by its influence.", sourceObjectiveStatus = "unverified-source-field" }
quests[30977] = { id = 30977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grounded Welcome", description = "All of my men are down at Farwatch Overlook to the southwest, holding off mantid that are trying to fly across the chasm. As long as my marksmen have arrows, they'll ground any mantid that clear the chasm.\n\nIf you're here to help, I could use some more men clearing the mantid out once they're on the ground. Are you willing, {class}?", sourceObjective = "Kill 12 grounded Kor'thik Fleetwings.", completion = "Your efforts are appreciated, {class}. Even a few more moment's breath between attacks are a relief these days.", sourceObjectiveStatus = "unverified-source-field" }
quests[30978] = { id = 30978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hostile Skies", description = "We're about to get hit hard... \n\nPick up that cannon there and lend a hand, if you would.  There will be no shortage of targets.", sourceObjective = "Shoot down 50 Kor'thik Swarmers and Voress'thalik.", progress = "I could really use you on that cannon...", completion = "Excellent shooting!\n\nI'm pretty sure that big bug survived the fall though...", sourceObjectiveStatus = "unverified-source-field" }
quests[30979] = { id = 30979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devastation Below", description = "Let's get down there and finish that big bug off, you and I.", sourceObjective = "Defeat Voress'thalik with the aid of Hawkmaster Nurong.", completion = "Where have you been all my life?!  That was amazing!\n\nI'd be proud to fight beside you any day.", sourceObjectiveStatus = "unverified-source-field" }
quests[30980] = { id = 30980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroes of the Shado-Pan", description = "You said that Taran Zhu is in Townlong and was asking for me?  Must be something important...", sourceObjective = "Return with Hawkmaster Nurong to Taran Zhu at Rensai's Watchpost.", completion = "I like that I can always depend on you. You have the spirit of a true Shado-Pan.", sourceObjectiveStatus = "unverified-source-field" }
quests[30981] = { id = 30981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taoshi and Korvexxis", description = "Taoshi is setting up an ambush for one of the mantid leaders on the south side of Sik'vess. She is tasked with retrieving his crystal so that we can use it to open the door.\n\nTwo are stronger than one. I want you there to make sure it goes smoothly.", sourceObjective = "Kill Korvexxis with the aid of Taoshi.", progress = "Our hunt is nearly over...", completion = "The first crystal is ours...", sourceObjectiveStatus = "unverified-source-field" }
quests[30982] = { id = 30982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animal Control", description = "The chasm is overrun with flame hounds and lava worms, and they will be entrenched indefinitely with such a large supply of trogg flesh for food.\n\nThis infestation needs to be taken care of now, before they endanger the city. You look like you can handle yourself, {name}.\n\nI want you to clear a path through the beasts and make certain to take out the largest threats, Adjules and Magnaw.", sourceObjective = "Kill Adarogg and Slagmaw.", completion = "Good work, {name}. Who knows what kind of destruction those beasts would have caused.", sourceObjectiveStatus = "unverified-source-field" }
quests[30983] = { id = 30983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Shaman", description = "These dark shaman have been down here for months, raising beasts and performing dark rituals.\n\nI don't know what they aim to achieve with all of this, but it's clear that they are no friend of the Horde. That's where you come in, {name}.\n\nFight your way through the chasm and kill Dark Shaman Koranthal and Lava Guard Gordoth.", sourceObjective = "Defeat Dark Shaman Koranthal and Lava Guard Gordoth.", completion = "It would seem that the dark shaman experiments drove Gordoth insane.\n\nHopefully we've seen the last of this, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30984] = { id = 30984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Orc Left Behind", description = "This was supposed to be a routine sweep, {name}. Clean up a few troggs, make sure there is no threat to the city and then be in the tavern by midday.\n\nInstead I've a group of scouts missing, flame hounds pouring out of the chasm and Xorenth going on about \"the next twilight's hammer.\"\n\n<Commander Bagran spits>\n\nGo in there and get my scouts back so we can figure out what is going on down here.", sourceObjective = "Rescue 5 Kor'kron Scouts in Ragefire Chasm.", progress = "Have you found the scouts?", completion = "That's all that survived?\n\nI don't know who these Dark Shaman are working for, but they are going to pay for this.", sourceObjectiveStatus = "unverified-source-field" }
quests[30986] = { id = 30986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Mogu Crypt", description = "Our scouting party got DESTROYED.  Help!", sourceObjective = "Kill the possessed Shado-Pan Leader and cleanse the Pool of Life.", sourceObjectiveStatus = "unverified-source-field" }
quests[30987] = { id = 30987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Alliance", description = "We have a duty, {name}.\n\nIt is our responsibility to spread the Tushui philosophy beyond the edges of the Wandering Isle... and there is no better place to start doing that than here: Stormwind City, heart of the Alliance.\n\nLet's find out who their leader is. We need allies.", sourceObjective = "Speak with King Varian Wrynn at Stormwind Keep.", completion = "{race}... you're here.\n\nGood.", sourceObjectiveStatus = "unverified-source-field" }
quests[30988] = { id = 30988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Way", description = "I only recently received word that some of your kind might be coming our way. I'd be glad to call you an ally, if you're willing to join our cause.\n\nWalk with me, {name}.", sourceObjective = "Walk with King Varian Wrynn.", completion = "Before you go, {name} - I have one more thing to discuss with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[30989] = { id = 30989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Old Pit Fighter", description = "I need to know if you can fight. There may come a time where you will be called upon for military matters, and I need to know that you can protect my kingdom.\n\nI've heard stories about pandaren fighting techniques, but I've never seen them in person.\n\nShall we?", sourceObjective = "Spar with King Varian Wrynn.", completion = "You've more than proven your worth, in battle and in heart. Few would be willing to leave their homeland to join the Alliance. Fewer still would be willing to face the King of Stormwind in combat.\n\nYou, and the rest of your people, are welcome among our ranks. Welcome to the Alliance, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30991] = { id = 30991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do a Barrel Roll!", description = "When I trained as a Brewmaster, I didn't expect to use my knowledge like this...\n\nDid you know beer catches fire when lit? Well, with yaungol oil mixed in, it's downright explosive.\n\nI've mixed the oil in with these kegs. Roll them at the yaungol over by the gate, and ignite them when you get close. \n\nIt'll take a few seconds for the keg to blow, but when it does...\n\nWell, let's just say I wouldn't want to be over there.\n\nWhich is why I'll be over here. Mourning the loss of this brew.", sourceObjective = "Pick up a keg near Lao-Chin, roll it downhill at the yaungol, and ignite it near them to destroy 4 Osul Treelaunchers and 50 Osul Invaders.", progress = "Wha? I was just thinking about my poor, poor beer...", completion = "Whoo, that was an explosion! Several, in fact.\n\nSad my beer had to go, but at least we're safe, for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[30992] = { id = 30992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish This!", description = "We've heard back from Suna, on the wall. Something's going on...\n\nIt looks like they are preparing for their final push. It's time to finish this, friend.", sourceObjective = "Finish the battle for the Ox Gate.", progress = "Lin is captured... we must break Taran Zhu from his complacence!", completion = "Well, their lieutenant is dead. I think we have finally pushed them out of Kun-Lai. \n\nBut at what cost? So many dead, Lin captured... I will not allow Taran Zhu to continue to ignore his charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[30993] = { id = 30993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where are My Reinforcements?", description = "This has simply gone too far. I cannot ignore our abandonment any longer.\n\nAfter all that's happened here, and all you've been through in Firebough, we must travel to the monastery.\n\nWhatever they are doing in there can wait! We can take my balloon up the mountain to the Monastery. It's anchored back by the camp, to the northeast.", sourceObjective = "Speak with Ban Bearheart outside the Shado-Pan Monastery in Kun-Lai Summit.", progress = "Here we are, then.", completion = "Here we are, and now you know why we cannot let our brothers sit idly by.", sourceObjectiveStatus = "unverified-source-field" }
quests[30994] = { id = 30994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lao-Chin's Gambit", description = "Alright. Thanks to you, we have the wall under control. Good job. \n\nI'll stay up here for a little while and make sure no more yaungol get up onto the wall.\n\nYou, though, should go back down and see what Lao-Chin has cooked up. I hate to say it, but maybe he had a good idea after all...", sourceObjective = "Speak with Lao-Chin the Iron Belly at Winter's Blossom in Kun-Lai Summit.", progress = "Ah, hello again. As sad as I am to have to do this, I'm glad I came up with something.", completion = "Good to see you made it back in one piece. Thanks to your help with the barrels, I've managed to brew up a good surprise for our yaungol friends at the front.", sourceObjectiveStatus = "unverified-source-field" }
quests[30995] = { id = 30995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Man Left Behind", description = "I sent recon out over an hour ago and none of them have reported back. And now these damned hounds are pouring out of the chasm.\n\nI don't know what's going on down there, but I'm not going anywhere till I get my men back.\n\nI want you to head in there and find them, {name}, preferably while they are still alive.", sourceObjective = "Rescue 5 SI:7 Rangers in Ragefire Chasm.", completion = "That's all that survived?\n\nThe Horde is going to pay for this in blood.", sourceObjectiveStatus = "unverified-source-field" }
quests[30996] = { id = 30996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Shaman", description = "These dark shaman have been down here for months, raising beasts and performing dark rituals.\n\nI don't know what they aim to achieve with all of this, but it's clear that they are no friend of the Alliance. And I need your help stopping them, {name}. \n\nFight your way through the chasm and kill Dark Shaman Koranthal and Lava Guard Gordoth.", sourceObjective = "Defeat Dark Shaman Koranthal and Lava Guard Gordoth.", completion = "It would seem that the dark shaman experiments drove Gordoth insane.\n\nHopefully we've seen the last of this, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[30997] = { id = 30997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animal Control", description = "I'm glad you're here, {name}. The horde is amassing an army and I'm not going to wait to find out why.\n\nWe need to strike fast and take down some of the larger beasts they have down here.\n\nI want you to head in there and take care of Adarogg and Slagmaw before the horde can use them as weapons against us.", sourceObjective = "Kill Adarogg and Slagmaw.", completion = "Good work, {name}. Who knows what kind of destruction those beasts would have caused.", sourceObjectiveStatus = "unverified-source-field" }
quests[30998] = { id = 30998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Enemy", description = "The horde is using dark magic to control beasts and corrupt their brethren down here, {name}.\n\nI intend to put a stop to it, but first I need to know what it is we're fighting against. That's where you come in.\n\nFight through the caverns and collect the insignia that the cultists carry. With them, I can study what type of magic is at work here.", sourceObjective = "Collect 5 Corrupted Insignia from the Dark Shaman cultists.", progress = "Have you collected the insignia?", completion = "Good work, {name}. Now we can figure out what it is they were trying to achieve down here.", sourceObjectiveStatus = "unverified-source-field" }
quests[30999] = { id = 30999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path Less Traveled", description = "The toughest roads often have the most to teach us, {class}. I will no doubt learn a great deal from following the path of Shaohao.\n\nMany years ago Shaohao traveled to the highest peak in Kun-Lai to seek the guidance of the Jade Serpent. I too will travel to Seeker's Point in search of wisdom.\n\nPerhaps you would be interested in a journey such as this? If so speak with Uncle Cloverleaf. He will help you prepare.", sourceObjective = "Speak to Uncle Cloverleaf in Onekeg.", completion = "Travel to Seeker's Point will require much good fortune, {class}. Hopefully you have many lucky trinkets!", sourceObjectiveStatus = "unverified-source-field" }
quests[31000] = { id = 31000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dread Space", description = "Shado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled {class} such as yourself.\n\nTake a kite and check in with Bowmistress Li.", sourceObjective = "Speak with Bowmistress Li on the Serpent's Spine.", completion = "A volunteer for Dread Wastes duty? I think you might be the first.\n\nPleased to meet you.", sourceObjectiveStatus = "unverified-source-field" }
quests[31001] = { id = 31001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falling Down", description = "It's bad enough trying to hold off the mantid, but now we've got spiders swarming up from the ruins below.\n\nOne of my best marksmen caught a blast of webbing around his leg and got pulled straight down!\n\nWe think he's alive, but I don't have the manpower to send anyone in after him. We're stretched thin up here, {class}.\n\nIf you want to help, use the rope behind me to drop down into the ruins. You're not afraid of heights are you?\n\nHow about spiders?", sourceObjective = "Use the Shado-Pan Rope to descend into the Terrace of Gurthan and search for the fallen Shado-Pan marksman.", completion = "The fall wasn't that bad, actually. I've always had a knack for soft landings.\n\nThat I landed on a pile of spider corpses probably helped, too.", sourceObjectiveStatus = "unverified-source-field" }
quests[31002] = { id = 31002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nope", description = "We're holding, but just barely. Anything you can do to stem the tide of dreadspinners coming up the wall would be a big help.\n\nFeel like tearing open spider eggs one at a time by hand?\n\nI didn't think so. Take one of our dragon guns and light it up down there. I wanna hear those puppies pop.", sourceObjective = "Slay 6 Dreadspinner Tenders and use the Shado-Pan Dragon Gun to destroy 20 Dreadspinner Eggs in the Terrace of Gurthan.", progress = "Hey, help me out here!", completion = "Nice work with that dragon gun. I did what I could down here, but arrows are only so useful against these things.", sourceObjectiveStatus = "unverified-source-field" }
quests[31003] = { id = 31003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Psycho Mantid", description = "You aren't going to believe what I saw! Two mantid fighting each other, whipping some serious magic back and forth.\n\nOne of them didn't look like any mantid I've ever seen. Completely different color and dress to him, like some kind of... oracle or something. The other one was a total psycho, splashing sha energy around like it was a keg of Stormstout Special.\n\nLook, I gotta get back to my post, but those two are still fighting in the cave behind me and I have a feeling it's a big deal. Check it out?", sourceObjective = "Investigate the mantid infighting at the Terrace of Gurthan.", progress = "The empress... is... misguided.", completion = "<This mantid is severely wounded. He barely manages to choke forth his words between wheezing gasps for breath.>\n\nHold, {race}...\n\nWe are... not your enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[31004] = { id = 31004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserved in Amber", description = "Take... this...\n\n<The dying mantid struggles to outstretch his arm. In his mangled grasp rests a metal fork with two long, thin prongs and an ornately jeweled handle.>\n\nAwaken... the Wind-Reaver...\n\nIt is the only way... to end the swarm.", sourceObjective = "Use the Klaxxi Tuning Fork on the Ancient Amber Chunk in the Terrace of Gurthan.", completion = "The Klaxxi... call to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[31005] = { id = 31005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wakening Sickness", description = "You will forgive my current state. I have slept for many years.\n\nA Klaxxi'va should have been here to attend my Wakening with kypari sap... but you will have to do.\n\nI sense the buzzing of sapflies to the south. They gorge on the nourishing sap I need. Bring them to me.", sourceObjective = "Bring 100 Sapfly Bits to Kil'ruk the Wind-Reaver in the Terrace of Gurthan.", progress = "Without nourishment, I will die where I stand.", completion = "This will do.", sourceObjectiveStatus = "unverified-source-field" }
quests[31006] = { id = 31006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Klaxxi Council", description = "I must report to the Klaxxi. They would not have woken me unless the situation were dire.\n\nYou have not been entirely useless. For that, I will spare your life.\n\nThe council may even find a use for you.", sourceObjective = "Travel to Klaxxi'vess at the center of the Dread Wastes. You may speak with Kil'ruk the Wind-Reaver in the Terrace of Gurthan for a ride, or travel on your own.", completion = "This is a sacred meeting place for the Klaxxi.\n\nIt would be wise of you to let me do the talking.", sourceObjectiveStatus = "unverified-source-field" }
quests[31007] = { id = 31007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dread Clutches", description = "The imperial clutches have become an abomination! Clutch-Keepers rush the development of new swarmborn, saturating them in this vile \"sha\" energy before sending them away to the wall.\n\nThe Klaxxi wish to stem the tide of swarmborn production in these dread clutches. Put the keepers to death!", sourceObjective = "Slay 6 Shek'zeer Clutch-Keepers in the Clutches of Shek'zeer.", completion = "A few less traitors for us to feed to the kunchong when the dust settles.", sourceObjectiveStatus = "unverified-source-field" }
quests[31008] = { id = 31008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amber Arms", description = "You! Filth!\n\nYou work for me now!\n\nThe amber blades of the Shek'zeer Bladesworn are the finest weapons in the empire.\n\nIf you are not impaled upon them immediately after leaving here, bring me as many of the blades as you can carry! I want to make sure we have weapons in reserve, should we need them.", sourceObjective = "Gather 6 Amber Blades from Shek'zeer Bladesworn around the Heart of Fear and The Clutches of Shek'zeer.\n\nSpeak with Kil'ruk the Wind-Reaver at Klaxxi'vess for a ride to the Heart of Fear.", progress = "The bladesworn carry their swords with pride. I want them on my weapon racks!", completion = "If all goes as planned, the Klaxxi will stop the Empress without your help. Still, it is my role to be prepared.", sourceObjectiveStatus = "unverified-source-field" }
quests[31009] = { id = 31009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dead Zone", description = "A Klaxxi'va whispers to the tower. It carries their whisper far; to other towers, to mantid, to paragons. The whisper bounces back, and the Klaxxi hear it.\n\nThis way, they see all.\n\nA tower near the palace is quiet. This will not do. It must sing for the Klaxxi.\n\nIt is my job to fix the tower, but if you serve the Klaxxi, you should serve me as well. You fix the tower, and I will wait here!", sourceObjective = "Use the Klaxxi Resonating Crystal on the Inactive Sonic Relay at the Heart of Fear.\n\nSpeak with Kil'ruk the Wind-Reaver at Klaxxi'vess for a ride to the Heart of Fear.", sourceObjectiveStatus = "unverified-source-field" }
quests[31010] = { id = 31010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Her Clutch", description = "The crystal sings to the Klaxxi. They sense a paragon in the clutch, east of the tower.\n\nClutch-keepers are trying to pollute this one. The Klaxxi will not permit this.\n\nGo and find the paragon. Place your hands on his chamber, and the Klaxxi will channel their whispers through you to break him free. Protect him if you can.", sourceObjective = "Locate and waken the mantid paragon in The Clutches of Shek'zeer.", completion = "My slumber was interrupted by sudden dreams. Unspeakable nightmares.\n\nThen I awoke.\n\nThe Klaxxi have spoken to me. I have my orders. There is much to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[31011] = { id = 31011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies At Our Door", description = "The Zandalari have begun their attack! You must help defend the village!\n\nIf we can't push them back, we will never find the Thunder King's remains!", sourceObjective = "Defeat 10 Amani Beserkers, 5 Amani Behemoths, and 3 Gurubashi Bloodriders.", progress = "The village must be saved!", completion = "The Zandalari have started to retreat, {name}. This victory will mean a great deal to the villagers.\n\nIn the chaos I was able to capture one of the fighters. Perhaps we can get information from him.", sourceObjectiveStatus = "unverified-source-field" }
quests[31012] = { id = 31012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Horde", description = "Here we are, {name}... Orgrimmar, heart of the Horde.\n\nWe can be helpful beyond the edges of the Wandering Isle. There are innumerable problems out there, just waiting for us to solve them. This is what Master Shang Xi would have wanted.\n\nThere's no better place to start doing that than here, with the aid of the Horde. Let's find out who their leader is. We need allies.", sourceObjective = "Speak with Garrosh Hellscream in Orgrimmar.", completion = "{race}... you're here.\n\nGood.", sourceObjectiveStatus = "unverified-source-field" }
quests[31013] = { id = 31013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Way", description = "I recently received word that some of your kind might be coming our way.\n\nI've recently been trying to bolster the strength of the Horde. A few pandaren might do us good.\n\nWalk with me, {name}.", sourceObjective = "Walk with Garrosh Hellscream.", completion = "Ji. {name}. You're here, good.\n\nLet's keep this moving.", sourceObjectiveStatus = "unverified-source-field" }
quests[31014] = { id = 31014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellscream's Gift", description = "I need to know if you can fight... that you can kill, and live. Eventually, each of you will be called upon for war, and I need to know that you can be counted on.\n\nI mentioned a gift earlier. It lies here, within the Ring of Valor. Step into the arena, right through this door behind me. I will test your skills.", sourceObjective = "Complete Garrosh's test by defeating Oggax, Gadoon, and Frozengore.", completion = "You've more than proven your worth, in battle and in heart. Few would be willing to leave their homeland to join the Horde. Fewer still would be willing to face a charging magnataur in combat.\n\nYou, and the rest of your people, are welcome among our ranks. Welcome to the Horde, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31015] = { id = 31015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Private Collection", description = "Pandaria is rich with history, legends, stories, and lore of every sort. While you are traveling throughout the world I would ask that you keep an eye open for artifacts and pieces of information that you feel would be pertinent to our work here.\n\nWhen you accumulate enough knowledge, we will compile it in to a volume for your personal collection here.\n\nYou can, of course, return whenever you like to review the volumes we are making for you.", sourceObjective = "Clean off the Empty Bookshelf.", progress = "So much to learn.", completion = "Ah! Now that that is done we can start to place your collected research here. I look forward to seeing what you find.", sourceObjectiveStatus = "unverified-source-field" }
quests[31016] = { id = 31016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lorewalkers", sourceObjective = "Speak with Lorewalker Cho at the Seat of Knowledge in the Vale of Eternal Blossoms.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
quests[31018] = { id = 31018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beneath the Heart of Fear", description = "The Klaxxi have detected the existence of another paragon, Wakener.\n\nThis one was kept well-hidden from us, and for good reason.\n\nThe Empress already has possession of this one, and her adjuncts work to destroy it even now.\n\nThey are performing their sorcery in a chamber deep beneath the palace, and they must be stopped.\n\nWe hold Klaxxi'vess. You must go in our stead. Find the entrance to their chamber from the ledge to the west.", sourceObjective = "Kill Adjunct Ek'vem, Adjunct Ikkess, Adjunct Suruz, and Adjunct Tsikzi, and then free Xaril the Poisoned Mind.", completion = "You have done your duty well, Wakener.", sourceObjectiveStatus = "unverified-source-field" }
quests[31019] = { id = 31019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amber Is Life", description = "In order for our efforts against the mantid empire to continue, we require more amber.\n\nThere is a great deposit of amber underneath the lake to the south, but the area is inhabited by a savage saurok tribe.\n\nI cannot spare anyone else. You must go to the lake and test the tribe's strength. Thin their numbers and eliminate their leader, who is probably hiding in his underground cavern.\n\nSurely this is not too great a task for you?", sourceObjective = "Kill 7 Mistblade Rippers and the Mistblade Scale-Lord.", progress = "The amber looks familiar for some reason...", completion = "The whispers seem to be emanating from within this amber.\n\nCould there be another paragon sleeping within?", sourceObjectiveStatus = "unverified-source-field" }
quests[31020] = { id = 31020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding the Beast", description = "I must join the Klaxxi Council and the other paragons immediately, but I am barely strong enough to stand.\n\nI must feed, Wakener.\n\nI sense the beating hearts of creatures on the northern bank of the lake.\n\nKill them for me, and I shall do the rest.", sourceObjective = "Kill 8 Coldbite Crocolisks.", progress = "I have been sleeping for many thousands of years. I must regain my strength before rejoining the Council.", completion = "I feel the strength returning to my body.", sourceObjectiveStatus = "unverified-source-field" }
quests[31021] = { id = 31021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Living Amber", description = "Liquid amber is most efficient for restoring a newly awakened paragon's strength, and is usually provided at a wakening ceremony.\n\nUnfortunately, it seems you did not receive these instructions, so we shall have to improvise.\n\nI can sense a vast quantity of fossilized amber in the lake below us. It will serve, but I am too weak to dig it up myself.\n\nDo this for me, and I will see to it that you are rewarded.", sourceObjective = "Collect 8 Living Amber, then feed them to Korven the Prime.", progress = "Do you understand, Wakener? The amber gives life.", completion = "Thank you, Wakener. That is enough for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[31022] = { id = 31022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kypari Zar", description = "What is that tree on the hill to the west? Can it be... Kypari Zar?\n\n<Korven the Prime lapses into silence.>\n\nWhen I returned from my final ravage, before being elevated to a paragon, I was given the honor of planting that very tree.\n\nI see it has grown into a great kypari, but... it seems something is amiss.\n\nThere is an old sonar tower at the base of the tree. Take me there, Wakener. I can use the tower to take a closer look.", sourceObjective = "Activate the Sonar Tower, then defend Korven the Prime as he examines the tree.", progress = "What has happened to our home? Things feel amiss.", completion = "Once, great rivers of amber coursed through this tree's veins. Now, it is but a dried husk.", sourceObjectiveStatus = "unverified-source-field" }
quests[31023] = { id = 31023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relics of the Swarm", description = "This strange-looking carving is covered in a complex written language that might be mantid in origin.\n\nYou notice more relics strewn carelessly among the camps and inside the lake.\n\nPerhaps the Klaxxi would be interested in examining these artifacts.\n\nWho knows? Perhaps it will earn you some favor.", sourceObjective = "Collect 8 Mantid Relics.", progress = "What do you have there?", completion = "These relics describe the history of Kypari Vos and the nearby amber trees.\n\nI would like to study these.\n\nThank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31024] = { id = 31024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kunchong Treats", description = "As Kovok grows, he will require equal parts discipline and reward.\n\nI lack no shortage of discipline, but our supply of meat is almost empty.\n\nTo the south, you will find turtles roaming north of the Lake of Stars and Kypari Zar.\n\nHunt them. Kovok likes the taste of their flesh.", sourceObjective = "Collect 4 Meaty Turtle Haunches.", progress = "What have you brought for Kovok?", completion = "Yes, a worthy feast.\n\nWell done.", sourceObjectiveStatus = "unverified-source-field" }
quests[31026] = { id = 31026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Root of the Problem", description = "Kypari Zar is dying.\n\nA creature of terrible darkness corrupts it from deep beneath its roots.\n\nThe tree cannot be saved, but at least we can lessen its pain.\n\nLook. The vile creature has carved a path to its own lair. We need only follow it down the hill, just behind this tower.", sourceObjective = "Kill the Coldbite Matriarch.", progress = "The swarm knows not of their terrible folly! These precious trees must be protected at all costs!", completion = "Thank you, Wakener. Kypari Zar can now dream in peace.\n\nHowever, the beast was merely a vessel for the corruption.\n\nNo... the true corruption lies much deeper.", sourceObjectiveStatus = "unverified-source-field" }
quests[31030] = { id = 31030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Monastery", description = "This... is unspeakable. If the monastery has truly been taken over by the Sha, we will need a great effort to purge the monks inside of corruption.\n\nGather a group of your allies, and meet me inside the Monastery.", sourceObjective = "Meet Ban Bearheart inside the Shado-Pan Monastery.", completion = "You have come. Good. This is a calamitous situation.", sourceObjectiveStatus = "unverified-source-field" }
quests[31031] = { id = 31031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Monastery", description = "This... is unspeakable. If the monastery has truly been taken over by the Sha, we will need a great effort to purge the monks inside of corruption.\n\nGather a group of your allies, and meet me inside the Monastery.", sourceObjective = "Meet Ban Bearheart inside the Shado-Pan Monastery.", sourceObjectiveStatus = "unverified-source-field" }
quests[31032] = { id = 31032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choking the Skies", description = "Nurong wants me to pass out torches for burning the bodies.\n\nThe flying mantid are fragile, and won't last long in the hot smoke.", sourceObjective = "Burn 10 Kor'thik Fleetwing corpses.", progress = "Some of them can make it through the smoke, but in small enough numbers that we can easily pick them off.", completion = "Your help is appreciated, stranger.", sourceObjectiveStatus = "unverified-source-field" }
quests[31034] = { id = 31034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "There are enemies of the Horde beneath this very city, {class}.\n\nThe Dark Shamans plot to take Orgrimmar for their own, and have already taken Ragefire Chasm! We need to storm their forces and retake what is ours!\n\nGo speak with Commander Bagran just inside Ragefire Chasm. He will have further orders for you.", sourceObjective = "Speak with Commander Bagran.", completion = "I've been expecting your arrival, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31036] = { id = 31036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "Orgrimmar's Ragefire Chasm has been taken by the Dark Shaman. {name}, we cannot allow this to pass unpunished, lest they next set their sights on Thunder Bluff.\n\nGo speak with Commander Bagran just inside the Chasm. Help him in any way you can, for our fates are intertwined.", sourceObjective = "Speak with Commander Bagran.", completion = "I've been expecting your arrival, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31037] = { id = 31037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemies Below", description = "With all his usual grace, Warchief Garrosh has kindly requested your presence in Ragefire Chasm to help retake it from the Dark Shaman. Apparently, his reinforced city isn't as impenetrable as he thought.\n\nGo speak with Commander Bagran just inside Ragefire, I'm sure he'll be glad to have competent help.", sourceObjective = "Speak with Commander Bagran.", completion = "I've been expecting your arrival, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31038] = { id = 31038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenger's Ring: Snow Blossom", description = "News of your feats has been traveling around the camp, {name}.\n\nIn fact, Snow Blossom would like to test your skill in battle.\n\nYou had best prepare yourself, {class}. She is not easily defeated.\n\nIf you can prove your worth to her, you will win a valuable friend.", sourceObjective = "Challenge Snow Blossom and defeat her in the Challenger's Ring.", progress = "How did it go?", completion = "Ahhhh, so you bested Snow Blossom in battle, did you?\n\nShe will be stinging from that loss for a while, I'd wager.\n\nHowever, you have done well to win her to your side.\n\nShe does not warm to strangers quickly, but through time, she will prove to be a loyal and dependable companion.", sourceObjectiveStatus = "unverified-source-field" }
quests[31039] = { id = 31039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mogu Menace", description = "Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest.\n\nThe island was supposedly uninhabited, so their presence is disturbing news.\n\nEven more disturbing is the fact that they are performing sinister experiments on the island.\n\nI need a capable {class} to check out the situation.\n\nThe Shan'ze are likely to give you trouble, and if they do, kill them.", sourceObjective = "Kill 12 Shan'ze Serpentbinders or Shan'ze Beastmasters.", progress = "How many were there?", completion = "The Shan'ze are up to something. Well done, {name}, but we must continue to monitor their actions.", sourceObjectiveStatus = "unverified-source-field" }
quests[31040] = { id = 31040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiteful Sprites", description = "The Darkwoods sprites on Shan'ze Dao have fallen to the mogu's domination.\n\nThe once sly tricksters are now the full servants of the Shan'ze. They grow bolder each day, stealing and killing to satisfy their masters.\n\nThey must be eliminated, but be careful. They may look harmless, but they are actually quite vicious.", sourceObjective = "Kill 30 Darkwoods Pixies or Darkwoods Charmers.", progress = "The sprites must do as their masters command.", completion = "Good work, {class}. Left unchecked, the sprites would soon outnumber our entire army.", sourceObjectiveStatus = "unverified-source-field" }
quests[31041] = { id = 31041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg Rescue!", description = "Eggs. Yes, you heard me right. I said eggs, and these aren't for eating.\n\nHave you ever seen a cloud serpent egg?\n\nThese rare eggs look like jewels, and were once worth their weight in solid gold.\n\nShan'ze Dao to the north normally teems with wild cloud serpents, but the mogu and the sprites have their eggs on lock-down.\n\nWe need to save as many of these precious eggs as we can.\n\nI'm counting on YOU, {name}.", sourceObjective = "Collect 8 Cloudrunner Eggs.", progress = "Did you find any eggs? The serpents lay their eggs in nests on the beach, but the wood sprites are also known to steal them whenever they can.", completion = "Gently, gently!\n\nThank you for recovering these eggs safely, {name}.\n\nI know a few Serpent Riders in the Jade Forest who will take good care of these.", sourceObjectiveStatus = "unverified-source-field" }
quests[31042] = { id = 31042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onyx Hearts", description = "The Shan'ze Serpentbinders dominate the minds of wild cloud serpents, but they also create their own dark creatures from stone, metal, blood, and ancient sorcery.\n\nTheir creations, the Onyx Stormclaws, guard the island to the northwest.\n\nI wish to study the magic binding these creatures. Bring me their hearts, so that I can better understand what sorcery we are up against.", sourceObjective = "Collect 4 Onyx Hearts.", progress = "The Onyx Stormclaws will never disobey their masters.", completion = "These will do well, {name}. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[31043] = { id = 31043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Arts", description = "It is said that Shan'ze Dao was once home to a great mogu temple.\n\nThere, the Shan'ze studied and practiced the art of subjugating the dead or inanimate.\n\nMuch of their knowledge still remains on the island to the northwest, buried among the ruins.\n\nWe need to get our hands on their knowledge - both to keep it out of their hands, and to understand the nature of their experiments.", sourceObjective = "Collect 8 Shan'ze Tablets.", progress = "Knowledge is powerful. That is why the mogu are so dangerous.", completion = "Well done, {name}.\n\nWe'll begin deciphering the writing on these tablets at once.", sourceObjectiveStatus = "unverified-source-field" }
quests[31044] = { id = 31044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bronze Claws", description = "Among the Shan'ze's fiercest and most loyal creations are their quilen.\n\nThese beasts will hunt until they kill their prey, or die in the process.\n\nI need you to not only cull their numbers, but also to retrieve their bronze claws.\n\nTheir claws are strong and razor sharp, and we can use them to make weapons and hooks for our cause.", sourceObjective = "Collect 20 Bronze Claws.", progress = "The quilen are fierce, but I see fierceness in your eyes as well.", completion = "These claws will come in handy.\n\nGood work, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31045] = { id = 31045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusions Of The Past", description = "{class}, I need your strength to eliminate the Shan'ze Illusionists on Shan'ze Dao, to the northwest.\n\nIt wearies me to ask of you this difficult task.\n\nThe illusionists are among the strongest of the Shan'ze's elite sorcerors.\n\nThey will not be easy to defeat, but I know no {class} who is better suited to the task.", sourceObjective = "Kill 3 Shan'ze Illusionists.", progress = "Do not be fooled by their illusions.", completion = "I knew you could do this, {name}!\n\nWith fewer Shan'ze Illusionists to stand against us, our task here will be much easier.", sourceObjectiveStatus = "unverified-source-field" }
quests[31046] = { id = 31046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Hatchlings", description = "I have seen the cruel experiments that the Shan'ze are performing on their island to the northwest.\n\nThe Shan'ze raise baby serpents from the egg. They keep the young in tiny cages, surrounded by squalor and filth.\n\nThe cruelest gaolers starve and torture them.\n\nWe must save as many hatchlings as we can. You have my full permission to punish any mogu that gets in your way!", sourceObjective = "Free 20 Cloudrunner Hatchlings.", progress = "The mogu are cruel beyond measure.", completion = "Those creatures will remember you as their savior.\n\nYou have done well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31047] = { id = 31047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Born Free", description = "Do you know the story of the great cloud serpents of Pandaria, {name}?\n\nSomeday you must hear it. Unfortunately, there is no time to tell it now.\n\nWhat you must know is that the wild cloudrunner serpents of Townlong are in trouble.\n\nThe mogu are capturing wild serpents and corrupting their minds, bending them to their sinister will.\n\nGo to Shan'ze Dao, to the northwest. Free the adult serpents from their chains. Save them!", sourceObjective = "Free 6 Wild Cloudrunners from their chains.", progress = "The wild cloudrunners should remain free.", completion = "Good work, {race}. It gladdens me to see that the wild serpents are free once again.", sourceObjectiveStatus = "unverified-source-field" }
quests[31048] = { id = 31048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grave Consequences", description = "We've found ancient mogu burial urns among the ruins on Shan'ze Dao.\n\nThis is normally no problem, except these urns are home to angry mogu spirits.\n\nNot only do these urns pose a danger to anyone unlucky enough to find one, but they could be used for destruction if they were to fall into the wrong hands.\n\nWe must rid Shan'ze Dao of their presence.", sourceObjective = "Kill 24 Shan'ze Ancestors. Shan'ze Ancestors may be found inside Mogu Burial Urns.", progress = "Did the spirits cause you any problems?", completion = "Good riddance, I say! Those mogu ghosts were long past their expiration.", sourceObjectiveStatus = "unverified-source-field" }
quests[31049] = { id = 31049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Sprite Of Everything", description = "The sprites of Shan'ze Dao have always been capricious tricksters, but now they have fallen under the mogu's influence.\n\nEven as we speak, they gather under a new leader.\n\nWe cannot allow this to happen.\n\nTheir mischievous pranks were one thing, but united, their dark magic is too powerful and too dangerous to comprehend.\n\nTake out their leader before it is too late.", sourceObjective = "Kill the Darkwoods Faerie.", progress = "The sprites are easily manipulated, and too dangerous to ignore.", completion = "Good work, {name}.\n\nThe wood sprites may look harmless, but that's what makes them so dangerous.", sourceObjectiveStatus = "unverified-source-field" }
quests[31055] = { id = 31055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Between a Saurok and a Hard Place", sourceObjective = "Bring Between a Saurok and a Hard Place to Lorewalker Cho.\n\nProvided item:", completion = "Before your research, I don't think pandarens ever really knew why the saurok were so vicious. We will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", sourceObjectiveStatus = "unverified-source-field" }
quests[31058] = { id = 31058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Funky Monkey Brew", description = "Pirates! Our shores have been scoured by the most ill-tempered, ill-mannered, ill-hygienic, and ill-good hozen that ever was found in Pandaria. And to make matters worse, they claim to serve the legendary Captain Ook!\n\nWe see them every night partying and brewing punch on their island Unga Ingoo.\n\n I say we take their brew for a change! I think I can even improve their mix.\n\nGather up some friends and meet me on the southern side of Unga Ingoo. It is time for a Brew Run!", sourceObjective = "Defeat Captain Ook.", progress = "These hozen pack some mean toys and some meaner brews.", completion = "A fine punch! A fine punch indeed! The sort of punch that punches back. Well done, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[31060] = { id = 31060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dawson test POI" }
quests[31061] = { id = 31061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding the Storm", description = "Shan Bu, the leader of the Shan'ze, is performing some kind of dark ritual at the summit of the island to the northwest.\n\nWe believe that the subjugated Shan'ze Cloudrunners are powering the spell. How, we still do not know.\n\nWe believe that the Shan'ze Cloudrunners can still be saved from the corruption that taints them.\n\nTake these bronze claws. Use them to mount the back of a Shan'ze Cloudrunner.\n\nAttack them. Beat some sense back into their heads!", sourceObjective = "Use the Bronze Claws to mount 8 Shan'ze Cloudrunners. Attack them to free them of their corruption.", progress = "How did it go?", completion = "We do not fully understand what the Shan'ze are doing, or the nature of their domination over the wild serpents.\n\nBan's theory is that the only thing that can cut through the mind control is physical pain.\n\nOnce the Shan'ze Cloudrunners feel enough pain, it looses the corruption's hold, and they finally remember who they are.", sourceObjectiveStatus = "unverified-source-field" }
quests[31062] = { id = 31062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When The Dead Speak", description = "The Shan'ze's experiments are overseen by a powerful necromancer known as a Shan'ze Deathspeaker.\n\nIf we are to put an end to their operations, we must eliminate their leader.", sourceObjective = "Kill the Shan'ze Deathspeaker.", progress = "What would possess the mogu to perform such hideous experiments?", completion = "Excellent work, {name}.\n\nI expected nothing less.", sourceObjectiveStatus = "unverified-source-field" }
quests[31063] = { id = 31063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lao-Chin and Serevex", description = "Lao-Chin is facing off against the leader just above the entrance in the tree, on the north side of Sik'vess. He is to bring back the second crystal that we need to get into the mantid tunnel.\n\nGo there and lend him your aid.", sourceObjective = "Kill Serevex with the aid of Lao-Chin the Iron Belly.", progress = "The Sha of Hatred dies this day...", completion = "We have the second crystal then. Good.", sourceObjectiveStatus = "unverified-source-field" }
quests[31064] = { id = 31064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nurong and Rothek", description = "Hawkmaster Nurong has gone ahead to the northwest of Sik'vess to make sure the last mantid leader cannot escape.\n\nCatch up with him and help him kill the mantid leader. Nurong will bring back the final crystal once you've aided him in this.", sourceObjective = "Kill Rothek with the aid of Hawkmaster Nurong.", progress = "Act swiftly. I do not want the Sha of Hatred to escape our grasp again.", completion = "The final crystal is ours. We are on the doorstep of our final confrontation.", sourceObjectiveStatus = "unverified-source-field" }
quests[31065] = { id = 31065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried Beneath", description = "Taoshi set up a spyglass on the ridge edge to show me what her scouting uncovered.\n\nGo over and take a look.", sourceObjective = "Look through the spyglass in Rensai's Watchpost.", progress = "Go. Look.", completion = "Our tasks lay before us.", sourceObjectiveStatus = "unverified-source-field" }
quests[31066] = { id = 31066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cry From Darkness", description = "So, you survived the imperial clutches. You are... resilient.\n\nThe Klaxxi hear another paragon to the north, among the sha-scorched roots of Kypari Vor.\n\nThis one cries out in terror and agony. It cannot be saved.\n\nThe Klaxxi want him put down. Go and defeat him or do not return here.", sourceObjective = "Slay the corrupted paragon at Kypari Vor.", progress = "The order stands. Slay the fallen paragon.", completion = "What?! How did you...\n\nThe Deathcaller was a legendary hero. He must not have been fully wakened.\n\nYou are fortunate.", sourceObjectiveStatus = "unverified-source-field" }
quests[31067] = { id = 31067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heavens Hum With War", description = "The mantid don't ever make my job easy, but now they've gone too far.\n\nWe can fend off the occasional attack from Kor'vess, but now... now they're starting to surround us. What's worse, they're draining the amber from our tree.\n\nThis will not stand! We need that amber! To make beer!\n\nThey've dug a burrow into the south side of the tree. I'm short-handed here. Could you take care of them for me?", sourceObjective = "Slay Azzix K'tai.", completion = "We're not here to hurt anybody. We just want to make a little bit of brew out of this tree sap. Is that too much to ask?", sourceObjectiveStatus = "unverified-source-field" }
quests[31068] = { id = 31068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacred Recipe", description = "\"When the horror comes a-rising\nAnd the heavens hum with war\nOur great vessel of salvation\nMust be broken from its core.\"\n\nThe scroll continues on for several stanzas. Perhaps somebody at The Sunset Brewgarden will be able to decipher its cryptic message.", sourceObjective = "Bring the Scroll of Auspice to Lya of Ten Songs at The Sunset Brewgarden.", progress = "Is that some sort of scroll?\n\nWould you mind if I took a look?", completion = "<Lya reads the entirety of the message.>\n\nThis scroll, this... this prophecy...\n\nIt's terrifying!", sourceObjectiveStatus = "unverified-source-field" }
quests[31069] = { id = 31069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound With Shade", description = "About that scroll you found...\n\nI keep looking at that line in the second stanza - \"bound with wood and shade\". The \"shade\", in particular, intrigues me.\n\nI must admit, I've often considered taking some of the area's residual sha essence and incorporating it into a brew. I suspect that this is the shade which our recipe calls for.\n\nYou will find large amalgamations of sha to the southeast of our tree... though you may also be able to harvest some from the local wildlife.", sourceObjective = "Harvest 100 drops of Shade by slaying sha creatures and wildlife near The Sunset Brewgarden.", completion = "Beautiful. This will make a fine addition to our brew.\n\nThe most dangerous ingredients are quite often the most delicious.", sourceObjectiveStatus = "unverified-source-field" }
quests[31070] = { id = 31070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daggers of the Great Ones", description = "That recipe said: \"rending daggers of the great ones\"...\n\n<Olon ponders this line.>\n\nMushan! That's it!\n\nThere's plenty of mushan roaming out there with these great, big teeth... they're as long as daggers. That's gotta be what the recipe calls for.", sourceObjective = "Obtain 3 Large Mushan Teeth.", progress = "I wonder how we'll mix those things into the brew? Can't grind them up - that'd be too gritty.\n\nMaybe I'll just soak 'em for a while.", completion = "I never thought of putting mushan teeth in a brew before.\n\nThat scroll's got some wacky ideas.", sourceObjectiveStatus = "unverified-source-field" }
quests[31071] = { id = 31071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Bring Us Great Shame", description = "I have failed my fellow brewers.\n\nI took some supplies out to the clearing, east of our tree... and I left them there. Now, with the sha corrupting the land, and the mantid on the prowl, it is too dangerous for me to bring them back.\n\nIf you would help me look for them, perhaps I could regain some of my lost honor.", sourceObjective = "Find the Lost Keg, the Lost Mugs, and the Lost Picnic Supplies.", progress = "Did you find them? Can it be?", completion = "You have brought me joy, traveler.", sourceObjectiveStatus = "unverified-source-field" }
quests[31072] = { id = 31072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rending Daggers", description = "Forget about them, and forget their BREW. We've got real work to do.\n\nThe scroll mentions \"rending daggers of the great ones\". I've got a feeling I know where to find them.\n\nA pair of mantid lieutenants patrol the Horrid March, to the south. Each one carries a ceremonial dagger.\n\nBring those daggers back here, {name}. We may be on the brink of something big.", sourceObjective = "Obtain the Blade of Kz'Kzik and the Blade of Ilikkax.", progress = "I think I'm starting to understand the next few lines of this prophecy, {name}.\n\nDo you have the daggers yet?", completion = "These daggers, look!\n\n<Lya holds the blades hilt-to-hilt.>\n\nThey were built to fit together! But how to join them...?", sourceObjectiveStatus = "unverified-source-field" }
quests[31073] = { id = 31073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound With Wood", description = "<Vu eyes the recipe.>\n\nHmm... \"bound with wood\". We don't typically brew with wood. Sap, yes... but not wood.\n\nWe have, on rare occasions, infused our drinks with corewood from the treants to the west of here. Most of them have fallen to the mantid... but their remains should suffice for our recipe.", sourceObjective = "Obtain 8 pieces of Fragrant Corewood.", progress = "We don't brew with wood here. It gives the brew a harsh, insipid flavor, not unlike that of wine.\n\n<Vu spits.>", completion = "I'll get these pieces prepared.\n\nWe've already gathered quite a few of these ingredients! I'll have to get a pot boiling soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[31074] = { id = 31074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wood and Shade", description = "\"Rending daggers of the great ones shall be bound with WOOD and SHADE.\"  Hmm.\n\nI've learned a lot about the Kor'thik mantid in my time here. I know that they maintain shrines within their settlement, Kor'vess.\n\nOne is a heartroot of the very tree that they inhabit. The other is a dark pillar, connecting them with their queen.\n\nThese shrines are the wood and shade. If my predictions are right... the daggers should react in their presence.", sourceObjective = "Find the Mark of the Empress and the Heartroot of Kypari Kor.", progress = "<Lya looks concerned.>", completion = "{name}, look! The daggers - they've bound together, into a forked blade.\n\nWe are on the right track. I knew this wasn't a beer recipe.", sourceObjectiveStatus = "unverified-source-field" }
quests[31075] = { id = 31075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunset Kings", description = "Olon had a clever idea. He thinks that we should visit the sprites to the west, and ask them if they have any of these ingredients. Some of the elements to this recipe are seeming... strange.\n\nThe Rikkitun sprites have a village to the west of Kor'vess. I hope to see you there, {name}.", sourceObjective = "Meet Sapmaster Vu at Rikkitun Village.", completion = "It's been a while since I brewed on the road.", sourceObjectiveStatus = "unverified-source-field" }
quests[31076] = { id = 31076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate of the Stormstouts", description = "Greetings, {race}. I am Chen Stormstout.\n\nI'm looking for my family. I am told that several Stormstouts came across the wall to help face the mantid threat. I mean to find them, and join them.\n\nHave you seen anyone named Stormstout come through here? Would you mind helping me ask around?", sourceObjective = "Ask the inhabitants of The Sunset Brewgarden if they've seen any Stormstouts.", progress = "You are brave to have come across the wall, {race}.", completion = "<Chen listens intently.>\n\nBig Dan, Han, Evie, and Mama. I understand.\n\nIt seems like Dan will be safe here. I will go look for Evie, Han, and Mama Stormstout.\n\nTravel well, {name}, and follow the Wanderer's Way.", sourceObjectiveStatus = "unverified-source-field" }
quests[31077] = { id = 31077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evie Stormstout", description = "I was too late. She was so small... and I was too late.\n\nShe should be given a proper burial. A little warrior like her deserves better than this.", sourceObjective = "Meet Chen Stormstout at The Sunset Brewgarden, then listen to his eulogy.", progress = "<Chen is in mourning.>", completion = "<Chen is, for the moment, silent.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31078] = { id = 31078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Han Stormstout", description = "There will be time for mourning later. For now, there are other Stormstouts to be found.\n\nThey say that Han Stormstout was last seen exploring Kor'vess. I suspect he headed into that mantid burrow, just across the way.\n\nYou should meet me down there, {name}. I don't doubt that I can handle a few mantid by myself... but I'd feel better with you by my side.", sourceObjective = "Find Han Stormstout in the Morrowchamber beneath Kor'vess.", progress = "I think I see someone over there, but I can't seem to get across these amber beams.", completion = "First Evie, now Han.\n\nI was too late again.", sourceObjectiveStatus = "unverified-source-field" }
quests[31079] = { id = 31079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horror Comes A-Rising", description = "We are protected from the mantid. Such was the agreement made so many millenia ago.\n\nThere are forces from which we are not safe, however. The kyparites beneath the ground to the west will haunt us, chase us... even eat us. The mistlurkers eat our kind by the handful.\n\nHelp our people, outsider. Defeat our enemies.", sourceObjective = "Slay 7 Shuffling Mistlurkers and 2 Kyparites.", progress = "We hate being eaten.", completion = "It is good to have someone of your colossal size in our village.\n\nYou have many uses.", sourceObjectiveStatus = "unverified-source-field" }
quests[31080] = { id = 31080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiery Wings", description = "I think that old paper said something about \"fiery wings.\" Those little dragons around here have wings. They're kind of fiery, in a way.\n\nYou're quicker than me. Try catching some of those dragons... or at least slapping the powder off of them.\n\nNo point in killing a harmless little dragon, if all you want is the sparkle from their wings.", sourceObjective = "Slap Rikkilea Flitterlings, then catch 88 flecks of Flitterling Dust.", progress = "I haven't been able to catch any of those things!", completion = "YEAH!!! FLITTERLING DUST!!!\n\n<Olon throws the powder into the pot.>\n\nThis brew is turning out... strange, and pretty smelly. I'm starting to think maybe Lya was right.", sourceObjectiveStatus = "unverified-source-field" }
quests[31081] = { id = 31081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incantations Fae and Primal", description = "I suspect we are going to need the help of these sprites.\n\nWe have two enchanted daggers, bound together with wood and shade. Now we need someone to perform ancient \"incantations\" on our artifact.\n\nBefore we ask for favors, let's show the sprites that we mean well. I heard their leader talking about a pair of mistlurkers that kidnapped several of their villagers. If we slay these fog beasts... we may get the \"incantation\" we need in return.", sourceObjective = "Slay Ahgunoss and Mygoness.", completion = "Nice work. I've heard the sprites talking about us.\n\nWe're getting their attention.", sourceObjectiveStatus = "unverified-source-field" }
quests[31082] = { id = 31082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Great Vessel of Salvation", description = "I know what you and the girl-panda seek. We can perform the rite for you... in time.\n\nFirst, I require aid. The seeds fall from our great mother-tree. It is our responsibility to collect them, even in dangerous times like these.\n\nEscort my chanters to the motherseeds, that they may bring them back to the collection pit.", sourceObjective = "Bring 3 Motherseeds to the collection pit in Rikkitun Village, with the assistance of the Rikkitun Chanters.\n\nYou can use the Rikkitun Bell to re-summon your chanters if you become separated.", progress = "The collection pit is down the hill, just to the west of here.", completion = "Yes, good. The motherseeds are taken care of.\n\nNow, we may speak of your enchantment.", sourceObjectiveStatus = "unverified-source-field" }
quests[31083] = { id = 31083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Promises of Gold", description = "As soon as the creature died, a strange group of sprites appeared and took its pearl away.\n\nThe sprites have a village nearby, called Rikkitun Village. Perhaps you should investigate.", sourceObjective = "Report to Chief Rikkitun at Rikkitun Village in Dread Wastes.", completion = "This shinyseed... it was your doing? I already had one shinyseed... but two is better.\n\nWe need only the seed, not the casing. If you like, you can keep.", sourceObjectiveStatus = "unverified-source-field" }
quests[31084] = { id = 31084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bind the Glamour", description = "It has been a very, very long time since our tribe has been called on to perform this rite. I will do the best I can.", sourceObjective = "Allow Chief Rikkitun to enchant the Forked Blade.", progress = "...", completion = "The blade is prepared.\n\nNow, only one task remains: you must use it.", sourceObjectiveStatus = "unverified-source-field" }
quests[31085] = { id = 31085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fires and Fears of Old", description = "We've found the blades, bound them together with wood and shade, and blessed them with an ancient incantation. If I'm not mistaken, it's time to use this thing.\n\nThe sprites spoke of an ancient piece of sap within the Amber Hibernal, a mantid cave near their empress' palace. That must be the \"Blood of Ancients\" that the prophecy spoke of.\n\nWhatever's inside that sap must be important. Good luck, {name}.", sourceObjective = "Use the Ruining Fork on Iyyokuk the Lucid, then protect him until he is able to escape.", progress = "Make sure to bring that forked blade with you.", completion = "There was a... a mantid inside that amber? I never would have thought that the solution to our war on the mantid would be... another mantid.\n\nThere are still many things that I have left to learn, but I do know this: that CERTAINLY wasn't a beer recipe.", sourceObjectiveStatus = "unverified-source-field" }
quests[31086] = { id = 31086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of Ancients", description = "Lya and I agree on one thing: \"Blood of Ancients\" is almost certainly the sap from the great trees of the area. I should know - I brew with the stuff all the time.\n\nThe most ancient tree of all is the one that Grand Empress Shek'zeer calls her home, now known as the Heart of Fear. Find some amber from that tree, and our brew should be complete.", sourceObjective = "Obtain a Chunk of Solidified Amber.", progress = "Any luck?", completion = "That should do it! Recipe... complete.\n\nNow let's see how this beer tastes.", sourceObjectiveStatus = "unverified-source-field" }
quests[31087] = { id = 31087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extending Our Coverage", description = "The Klaxxi'va hear another paragon. His cries are weak and lost in darkness. The signal must be strengthened.\n\nThere is a tower in Amberglow Hollow that has been silent for many years. It must sing; the Klaxxi demand it!\n\nThis time I will go with you. You will help me repair it.\n\nTake the resonating crystal and meet me in Amberglow.", sourceObjective = "Activate the Resonating Beacon in Amberglow Hollow.", completion = "It is good you showed up when you did.\n\nPerhaps you are not as useless as I thought...\n\nThe Klaxxi'va sing to the paragon now. Soon they will know where to send you. For now there are other tasks.", sourceObjectiveStatus = "unverified-source-field" }
quests[31088] = { id = 31088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crime and Punishment", description = "The Stinging Trail nurtures young Kypari trees. The empress drains the saplings too early, outsider. They must grow before the amber can be taken.\n\nThe Klaxxi'va demand punishment for this crime! It will please them if you rain death on the Ik'thik harvesters.", sourceObjective = "Kill 8 Ik'thik Harvesters on the Stinging Trail.", progress = "Have the harvesters been punished?", completion = "The Klaxxi are pleased with our work, outsider. You have proven to be more resourceful than we thought.", sourceObjectiveStatus = "unverified-source-field" }
quests[31089] = { id = 31089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By the Sea, Nevermore", description = "The Klaxxi'va have spoken to me, outsider. The paragon is hidden in the Briny Muck only, he is not so hidden anymore.\n\nThe lizard men surround him. He cannot fall into their scaley hands.\n\nYou will find him; you will awaken him. Do not return without him!\n\nIf you do this the Klaxxi will be pleased with us.", sourceObjective = "Use the Klaxxi Tuning Fork on the Ocean-Worn Rocks to awaken the paragon.", completion = "What... what sort of creature are you?\n\nHow have you awoken me?", sourceObjectiveStatus = "unverified-source-field" }
quests[31090] = { id = 31090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Better With Age", description = "It is a crime to harvest the young trees, but a much bigger crime to waste the amber.\n\nYoung amber is not as strong, but the Klaxxi need it to continue the fight. We will bring them more and they will sing my praises!\n\nGather the young amber. We will store it until it is aged and can be consumed.", sourceObjective = "Gather 7 Amber-Filled Jars from the Amber Collectors on the Stinging Trail.", progress = "I would go with you to gather amber, but my talents are more useful here.", completion = "Even this raw amber will be of use. We can't afford to be picky in times like these.\n\nThe Klaxxi'va will be glad I thought of this. I will tell them you helped!", sourceObjectiveStatus = "unverified-source-field" }
quests[31091] = { id = 31091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reunited", description = "You look at me and see I am no great warrior. Why was I chosen to be a Paragon? Not all weapons can be seen, Wakener. One should not judge by appearance alone.\n\nBefore I explain further, I need to know that you are trustworthy.\n\nSomething precious to me was hidden at the time of my preservation. I am nothing without it.\n\nDefend me as I unearth my greatest weapon, and you will have my trust.", sourceObjective = "Assist Kaz'tik the Manipulator as he unearths his greatest weapon.", completion = "Kovok is just as impressive as the last time I saw him. He will ensure great victories for the Klaxxi.", sourceObjectiveStatus = "unverified-source-field" }
quests[31092] = { id = 31092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feed or Be Eaten", description = "After years of working with the Kunchong I developed a theory; raising one from infancy would strengthen the bond and therefore strengthen the sonic connection.\n\nI had just begun training Kovok when I was chosen for encasement. He is still very young and will need diligent training to reach his full potential.\n\nI'm entrusting Kovok to you, but be warned; if any harm comes to him your life is forfeit.\n\nFirst, you must feed him to gain his trust. The turtles in the area should be suitable for this.", sourceObjective = "Begin Kovok's training by feeding him 6 Succulent Turtle Filets found on the Brineshell Snappers in the Briny Muck.", completion = "Very good! I had half expected Kovok to just eat you. What a pleasant surprise to see you both in one piece,\n\nPerhaps Kunchong raising is in your blood.", sourceObjectiveStatus = "unverified-source-field" }
quests[31093] = { id = 31093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hozen in the Mist", sourceObjective = "Bring Hozen in the Mist to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "Hozen are, by their very nature, a rambunctious lot.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", sourceObjectiveStatus = "unverified-source-field" }
quests[31094] = { id = 31094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Tales", sourceObjective = "Bring Fish Tails to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "This is a real treat. I always did enjoy the jinyu. Such a peaceful people with a real appreciation for wisdom.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", sourceObjectiveStatus = "unverified-source-field" }
quests[31095] = { id = 31095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Heart of the Mogu", sourceObjective = "Bring The Dark Heart of the Mogu to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "Mogu. Even the word makes my fur stand on end. We will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", sourceObjectiveStatus = "unverified-source-field" }
quests[31096] = { id = 31096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What is Worth Fighting For", sourceObjective = "Bring What is Worth Fighting For to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "Who would have thought the freedom of the pandaren people would begin with a single punch.\n\n Wonderful. We will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", sourceObjectiveStatus = "unverified-source-field" }
quests[31097] = { id = 31097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of the Mantid Swarm", sourceObjective = "Bring Heart of the Mantid Swarm to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "When we began this research project I never thought I would learn so much about such a terrifying people.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", sourceObjectiveStatus = "unverified-source-field" }
quests[31100] = { id = 31100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Song of the Yaungol", sourceObjective = "Bring The Song of the Yaungol to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "The yaungol are a warring people strengthened by their exile beyond the wall. We will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", sourceObjectiveStatus = "unverified-source-field" }
quests[31102] = { id = 31102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seven Burdens of Shaohao", sourceObjective = "Bring The Seven Burdens of Shaohao to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "This is a story I have long sought to uncover. Ever since the Sha was released I have felt in my belly that this tale was at the heart of it all.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", sourceObjectiveStatus = "unverified-source-field" }
quests[31103] = { id = 31103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ballad of Liu Lang", sourceObjective = "Bring The Ballad of Liu Lang to Lorewalker Cho at the Seat of Knowledge.\n\nProvided item:", completion = "The long lost story of Lou Lang and his Wandering Isle. This is a superb addition to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection.", sourceObjectiveStatus = "unverified-source-field" }
quests[31104] = { id = 31104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenger's Ring: Yalia Sagewhisper", description = "The Shado-Pan brothers and sisters continue to whisper of your deeds, {name}.\n\nIn fact, Yalia herself has taken quite an interest in your studies.\n\nShe wishes to challenge you in the training ring.\n\nYou would do well to impress her. If you do, she just may be willing to help you in the future.", sourceObjective = "Challenge Yalia Sagewhisper and defeat her in the Challenger's Ring.", progress = "Did you speak to Yalia?", completion = "You did it! You bested Yalia!\n\nYou have most definitely earned her favor, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31105] = { id = 31105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mogu Menace", description = "Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest.\n\nThe island was supposedly uninhabited, so their presence is disturbing news.\n\nEven more disturbing is the fact that they are performing sinister experiments on the island.\n\nI need a capable {class} to check out the situation.\n\nThe Shan'ze are likely to give you trouble, and if they do, kill them.", sourceObjective = "Kill 12 Shan'ze Serpentbinders or Shan'ze Beastmasters.", progress = "How many were there?", completion = "The Shan'ze are up to something. Well done, {name}, but we must continue to monitor their actions.", sourceObjectiveStatus = "unverified-source-field" }
quests[31106] = { id = 31106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mogu Menace", description = "Our scouts have discovered a heavy mogu force at Shan'ze Dao to the northwest.\n\nThe island was supposedly uninhabited, so their presence is disturbing news.\n\nEven more disturbing is the fact that they are performing sinister experiments on the island.\n\nI need a capable {class} to check out the situation.\n\nThe Shan'ze are likely to give you trouble, and if they do, kill them.", sourceObjective = "Kill 12 Shan'ze Serpentbinders or Shan'ze Beastmasters.", progress = "How many were there?", completion = "The Shan'ze are up to something. Well done, {name}, but we must continue to monitor their actions.", sourceObjectiveStatus = "unverified-source-field" }
quests[31107] = { id = 31107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Citizens of a New Empire", description = "At Shek'zeer's command, the great kypari tree of Kypari Vor was twisted into a totem of horror.\n\nLike those outside of the palace, the clutch nearby is now used to corrupt our swarmborn.\n\nRecover the eggs of the Vor'thik before they are tainted. We shall raise them here. They will be the citizens of a new empire, free from the sha.", sourceObjective = "Gather 10 Vor'thik Eggs from Kypari Vor.", progress = "Kypari Vor was beautiful once. Rich with amber and surrounded by prime hunting grounds.", completion = "They are large. They will hatch soon.\n\nGood. We may need them.", sourceObjectiveStatus = "unverified-source-field" }
quests[31108] = { id = 31108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Concentrated Fear", description = "Amber is power. It brings life.\n\nThis... dread amber you brought me has been twisted. It is concentrated fear.\n\nThe Vor'thik know this well. Their kypari has been completely engulfed by sha, and they use the dread amber to quicken their own swarmborn.\n\nBring me the crystals used by the Vor'thik fear-shapers in their rituals. The Klaxxi will study them and decide on a protocol for disposal.", sourceObjective = "Gather 4 Dread Amber Foci from Vor'thik Fear-Shapers at Kypari Vor.", progress = "Do you have the crystals?", completion = "What would happen, I wonder, if you ate one? What would it do to your soft, pink insides?", sourceObjectiveStatus = "unverified-source-field" }
quests[31109] = { id = 31109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Swarm", description = "The Empress continues to amass her forces. Without intervention, they WILL overrun that wall - even if it means smothering it in the corpses of a million swarmborn.\n\nLet us find a better place for those corpses.\n\nLet me know when you are ready to depart for the clutches - I will gladly drop you in from above.", sourceObjective = "Slay 40 Shek'zeer Mantid in the Clutches of Shek'zeer. Speak with Kil'ruk the Wind-Reaver for an air-drop.", progress = "We must kill faster than they can multiply. It is that simple.", completion = "This will do, for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[31110] = { id = 31110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Portal", description = "Ah, just the {class} I wanted to see!\n\nWe've finally figured out why the portal is not working. We need more arcane powder!\n\nIt would take us months to get a shipment sent out to us, but luckily, the mogu on this island carry plenty for their own spells.\n\nThey tend to use some older stuff, so we're going to need a lot of it.", sourceObjective = "Collect 1000 Ancient Arcane Powder.", progress = "Did you find the powders?", completion = "Excellent! Excellent!\n\nThis is just the stuff, {name}.\n\nWe'll get to work right away. I have no doubt we'll be done very soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[31111] = { id = 31111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eradicating the Zan'thik", description = "The warriors of Zan'vess are some of the most feared and respected in the empire, for good reason.\n\nImpalers are unmatched in their mastery of the polearm - no doubt Malik trained among the Zan'thik in his time. Their manipulators command terrifying sonic power with the ease and subtlety of a breath.\n\nBoth will need to be dealt with.", sourceObjective = "Kill 6 Zan'thik Impalers and 6 Zan'thik Manipulators in Zan'vess.", completion = "I will admit, Wakener, I am impressed.", sourceObjectiveStatus = "unverified-source-field" }
quests[31112] = { id = 31112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They're So Thorny!", description = "The crate, once full of desperately needed supplies, has been thoroughly pillaged.\n\nA quick scan of the area shows evidence left behind by the thieves. Icy thorns, just like the ones on the water sprites on the shoreline to the east.\n\nThis is a life or death situation for your band of survivors. Those supplies need to be retrieved from these thieving pests and returned to camp.", sourceObjective = "Collect 5 Emergency Supplies from the Water Sprites.", progress = "You manage to get your hands on them supplies, pal?", completion = "Look at that!\n\nThese supplies should keep us kickin' for a few more days.\n\nAnd my boots! Ya managed not to blow 'em up. Way ta go, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[31113] = { id = 31113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault Fire Camp Gai-Cho", description = "The Yaungol are a constant nuisance, but the group at Fire Camp Gai-Cho, to the northeast, conspired with the Osul yaungol in their recent incursion into Kun-Lai.\n\nWe cannot allow such an incursion to go unpunished.\n\nGo, attack Fire Camp Gai-Cho. We need to make sure they remain occupied, so that they cannot rise up and threaten The Ox Gate again.", sourceObjective = "Kill 16 Gai-Cho Yaungol, Earthtalkers or Pitchthrowers.", progress = "Is your raid on Gai-Cho complete?", completion = "Well - that should certainly deter any attack for a while. Good work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31114] = { id = 31114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault Deadtalker's Plateau", description = "We have always left the Deadtalkers alone. For so long, they were just responsible for maintaining the sacred burial grounds of the yaungol tribes.\n\nNow, though, they are practicing dark magic, defiling the corpses of their former clanmates... \n\nI know not where they learned those dark magics, or why they no longer treat their dead with respect, but we do not have time to find out. \n\nWe need to stop them.", sourceObjective = "Kill 8 Deadtalker Corpsedefilers and 1 Deadtalker Crusher.", progress = "Have you defeated the Deadtalkers?", completion = "By conspiring to use these dark magics, the Deadtalkers have given up their rights to protection. Your actions should deter them from their current course, I hope.", sourceObjectiveStatus = "unverified-source-field" }
quests[31116] = { id = 31116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit Dust", description = "The spirits that the Yaungol are entrapping from the remains of their ancestors still have a bit of the essence of life within them. \n\nIf you defeat the spirits in battle, you can collect essence from the spirits as dust, and then return it to the corpses in the area, which will send the spirits, finally, to the next life.\n\nThis is the only way to set right what the Deadtalkers have done. It will also help keep us safe.", sourceObjective = "Return 8 spirits to their remains at the Deadtalker Plateau in Townlong Steppes.", completion = "Good, you have helped right this terrible wrong.", sourceObjectiveStatus = "unverified-source-field" }
quests[31117] = { id = 31117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uruk!", description = "Uruk is the Deadtalker of the Townlong yaungol. Your mission will not be truly complete until you defeat him. Go to it!", sourceObjective = "Kill Uruk at Deadtalker's Plateau in Townlong Steppes.", completion = "Uruk is dead! This threat has subsided, at least for today. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31118] = { id = 31118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deadtalker Cipher", description = "We need to understand what went wrong with the Deadtalkers. \n\nFor so many years, the Deadtalkers were simply responsible for maintaining the burial grounds and holding funerals for fallen warriors.\n\nFrom a recent raid, we've recovered a tablet from the grounds that is clearly written using a cipher, but it isn't one we've encountered before. If you can gather a ciphered scroll from one of the Deadtalkers, we can begin to put together the cypher and understand what's happened.", sourceObjective = "Collect a Scroll of Spiritbinding Rites from the yaungol at Deadtalker's Plateau.", sourceObjectiveStatus = "unverified-source-field" }
quests[31119] = { id = 31119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enemy of My Enemy... Is Still My Enemy!", description = "The mantid are our enemies. As are the yaungol at Fire Camp Gai-Cho.\n\nIt is fortunate, then, that they are also each other's enemies. Mantid from Kri'vess constantly attack the Gai-Cho yaungol, who hold them off at their front gates.\n\nI want you to wreak havoc. \"Borrow\" some highly explosive oil barrels from camp Gai-Cho, and toss them down onto the battlefield from the air.\n\nI don't care which ones you kill, just kill a lot of them.", sourceObjective = "Use Highly Explosive Yaungol Oil Barrels to kill 100 mantid or yaungol on the Gai-Cho Battlefield.", progress = "How goes the battle?", completion = "Ha! Good work. Teaches both of them to make enemies of the Shado-Pan.", sourceObjectiveStatus = "unverified-source-field" }
quests[31120] = { id = 31120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cheng Bo!", description = "Cheng Bo is the Warbringer of Fire Camp Gai-Cho. While you've made a dent in their operations, you now have an opportunity to strike a major blow. \n\nSlay the Warbringer!", sourceObjective = "Kill Cheng-Bo at Fire Camp Gai-Cho in Townlong Steppes", progress = "How goes the assualt?", completion = "With Cheng Bo subdued, we can refocus our efforts on our other enemies. Your efforts earn you much respect, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31121] = { id = 31121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stay a While, and Listen", description = "Rush rush rush - are your people always in such a hurry?\n\nSit and have some tea with me a moment, and we will discuss your plight.\n\n<Lorewalker Cho's features settle into a patient smile.>", sourceObjective = "Drink from Cho's Teapot.", progress = "I hope I didn't bore you, traveler.", completion = "I will help you, traveler, but first I would like to learn a little about this Horde of yours...", sourceObjectiveStatus = "unverified-source-field" }
quests[31127] = { id = 31127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenger's Ring: Chao the Voice", sourceObjective = "Challenge Chao the Voice, and then defeat her in combat at Shado-Pan Garrison in Townlong Steppes.", progress = "Well? How did it go?", completion = "I'm sure there's no hard feelings. She just loves a good fight.\n\nYou should talk to her next time I have some missions for you. She's quite an able fighter, as I'm sure you saw.", sourceObjectiveStatus = "unverified-source-field" }
quests[31128] = { id = 31128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenger's Ring: Lao-Chin the Iron Belly", description = "Lao-Chin seems to have his head in the clouds... or, rather, in his beer.\n\nAfter all of his recent battles, he seems completely obsessed with with trying to develop the perfect brew for fighting. \n\nThat's well and good, but we need him to actually do some fighting!\n\nYou should go challenge him, see if you can snap him out of his rut. \n\nIf you beat him, he'll probably want to go out and help fight just to try to one-up you!", sourceObjective = "Challenge Lao-Chen the Iron Belly and then defeat him in combat at Shado-Pan Garrison in Townlong Steppes.", progress = "Well?", completion = "Wow, you must have impressed Lao-Chin. He can't stop talking about how excited he is to go out and fight with you. Good work.", sourceObjectiveStatus = "unverified-source-field" }
quests[31129] = { id = 31129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate of the Stormstouts", sourceObjective = "Ask the inhabitants of The Sunset Brewgarden if they've seen any Stormstouts.", progress = "You are brave to have come across the wall, {race}.", completion = "<Chen listens intently.>\n\nBig Dan, Han, Evie, and Mama. I understand.\n\nIt seems like Dan will be safe here. I will go look for Evie, Han, and Mama Stormstout.\n\nTake care, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31130] = { id = 31130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visit with Lorewalker Cho", description = "Stranger, I may be able to help you find your prince. But first, I would like to know a little more about you and your people.\n\nCome, help me with my chores, and we will chat.\n\nYou have the look of a grizzled war veteran, but certainly you have a few minutes to help a bookish Pandaren like myself putter around the house, yes?", sourceObjective = "Befriend Lorewalker Cho by assisting him around his house: Trim his tree, paint his wall, and feed his birds.", progress = "There is nothing like a little manual labor to bring strangers together, don't you think?", completion = "Despite your many years of combat, you've still got an eye for beauty, {name}. I like that about you!\n\nNow, let's find this missing prince of yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[31131] = { id = 31131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whitepetal Lake", description = "Reports suggest that things are quiet at Whitepetal Lake today, but I've dispatched Ren Firetongue and He Softfoot to make sure it stays they way.\n\nIf you want to aid the effort further, head to the west to the lake, meet up with He, and help him keep things secure from any hostile threats.", sourceObjective = "Speak to He Softfoot at Whitepetal Lake.", completion = "<He Softfoot smiles at you as you approach.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31132] = { id = 31132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mile in My Shoes", description = "Oh, where have my manners gone? Technically, I suppose I am the host here.\n\nAllow me to tell you a little bit about myself and my people before asking questions of you.", sourceObjective = "Speak to Lorewalker Cho at the Circle of Bone.", completion = "I suppose the best way to explain what a Lorewalker is all about is to show you...", sourceObjectiveStatus = "unverified-source-field" }
quests[31133] = { id = 31133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kor'thik Aggression", description = "I'm no brewer - just looking at all those heaps of ingredients makes my head spin. Just put the brew in front of me when it's finished, thank you.\n\nNo, I'm here to make sure that the brewers don't get cut in half while they're trying to make that perfect brew. It's not an easy job.\n\nThe Kor'thik mantid across this basin have been attacking us nightly. If you're already heading over there, why don't you return the favor and attack a few of them?", sourceObjective = "Slay 17 Kor'thik Mantid at Kor'vess.", progress = "Can't stand those mantid.", completion = "You've got the makings of a fine brewgarden guard, {race}. Let me know if you ever get tired of the whole \"{class}\" thing.", sourceObjectiveStatus = "unverified-source-field" }
quests[31134] = { id = 31134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If These Stones Could Speak", description = "This is a very ancient place, traveler.\n\nOnly recently have I pieced together a method of translating the forgotten language carved into these stones.\n\nOh, the thrill of discovery! This never gets old, I assure you.\n\nHere, you are the guest. You do the honors. I insist.\n\nUse this key to unlock the secrets the stones contain.", sourceObjective = "Use the Stone Monoliths at the Circle of Bone.", progress = "Your assistance is most appreciated, traveler.", completion = "That is enough translating for one day, I think.\n\nThis experience has been an enlightening one, I hope.", sourceObjectiveStatus = "unverified-source-field" }
quests[31135] = { id = 31135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\nXi, Friend of the Small has visited us from a faraway land and will help oversee your training and adjustment to life on the surface. She's waiting for you on the small practice field across the road.", sourceObjective = "Meet with Xi, Friend of the Small in New Tinkertown.", completion = "Why, you look great! I've heard bad things about what happens down there.\n\nWell, are you ready to start your training in the ways of the {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[31136] = { id = 31136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Our Lines", description = "Scouts bring me reports of a powerful Imperion that slipped through our lines in the south and is now heading for the road in the eastern vale.\n\nI need someone I can trust to stop it. Find it and kill it quickly, {name}.", sourceObjective = "Kill General Temuja.", progress = "Did you hunt down the Imperion as I requested?", completion = "Well fought. I hope to see more of you soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[31137] = { id = 31137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin and the other gnomes have mentioned that memory loss is pretty common for you survivors.\n\nAnyways, High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", sourceObjective = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", completion = "It's good to meet you, {name}. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[31138] = { id = 31138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Monk", description = "When you fight, you grow in skill. As you grow in skill, you will begin to figure out new moves. Go, explore, learn, and show me what you figure out.", sourceObjective = "Reach level 3 to learn Tiger Palm. Once you've learned it, use it twice at a Training Dummy in New Tinkertown.", completion = "You picked that one up quickly. I can't wait to show you some of my other favorite tricks.", sourceObjectiveStatus = "unverified-source-field" }
quests[31139] = { id = 31139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating Them Back!", description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander of this garrison. Glad to have you on board...\n\n<McBride looks through some papers.>\n\n{name}. It is {name}, right?\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", sourceObjective = "Kill 6 Blackrock Battle Worgs.", progress = "Have you beaten back the Blackrock battle worgs?", completion = "You've bought us a little time, {name}, but we've got even bigger problems to deal with now.", sourceObjectiveStatus = "unverified-source-field" }
quests[31140] = { id = 31140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lions for Lambs", description = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage.\n\nIn the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", sourceObjective = "Kill 8 Blackrock Spies.", completion = "Excellent work, {name}. You've turned out to be quite an asset to this garrison. It's time for you to train!", sourceObjectiveStatus = "unverified-source-field" }
quests[31141] = { id = 31141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calligraphed Letter", description = "I was asked to bring this to your attention as soon as you returned from dealing with the Blackrock spies, {name}. It appears to be a letter sealed with the insignia of Bao, a pandaren who is visiting us from a faraway land. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", sourceObjective = "Read the Calligraphed Letter and speak to Bao in Northshire Abbey.", progress = "Ah, you got my letter, {name}... good.\nI've come from afar to teach your people the ways of the {class}.", completion = "I  have come from very far to train you in the ways of our people. Do not hesitate to come to me for training whenever you like.", sourceObjectiveStatus = "unverified-source-field" }
quests[31142] = { id = 31142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Palm of the Tiger", description = "Now that you've had the chance to test your abilities in battle, it's time to explain one more reason why training is so important.\n\nAs you get more experience, you'll be able to do new techniques you never thought of.\n\nGo, get some experience, learn a new skill, and demonstrate it on one of the training dummies.", sourceObjective = "Reach level 3 to learn Tiger Palm, then practice using it on a Training Dummy south of the entrance to Northshire Abbey.", progress = "Well, did you give it a try?", completion = "You're a quick learner, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31143] = { id = 31143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Join the Battle!", description = "While you were out training I received an urgent message from Sergeant Willem. Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, {name}!\n\nFind Sergeant Willem north of the abbey at the command tent. Go!", sourceObjective = "Report to Sergeant Willem behind Northshire Abbey in Elwynn Forest.", completion = "It's true, we were ambushed. I don't dare send any more soldiers out there and risk losing them too. I need a volunteer. Someone willing to risk their life!", sourceObjectiveStatus = "unverified-source-field" }
quests[31144] = { id = 31144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Sent Assassins", description = "Have you ever seen a goblin, {name}? They're wretched little green-skinned monsters that love only two things: gold and themselves.\n\nThe Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass.\n\nI need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!", sourceObjective = "Kill 8 Goblin Assassins.", completion = "That will teach those monsters! They'll think twice before taking another mercenary job for orcs.", sourceObjectiveStatus = "unverified-source-field" }
quests[31145] = { id = 31145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rear is Clear", description = "Excellent work, {name}! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.\n\nFarewell, {class}.", sourceObjective = "Report to Marshal McBride in front of Northshire Abbey in Elwynn Forest.", completion = "With your help we have managed to secure the northern and western sectors of Northshire. We still have a rather large contingency of Blackrock orcs to the east and they've begun burning down the forest!", sourceObjectiveStatus = "unverified-source-field" }
quests[31146] = { id = 31146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scribbled Scroll", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. The pandaren visitor, Ting, sent it for you. Maybe you monks can read this garbage, but I can't. You should go talk to her. She's in the Inn across the way.", sourceObjective = "Read the Elegant Scroll and speak to Ting, Strong of Stomach in Deathknell.", progress = "Oh, yes, I sent that for you. I hope to prove that Forsaken can learn the arts of the {class} - perhaps you can help?", completion = "Yes, you can come to me to learn more about our people and our ways, especially when it comes to the arts of the {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31147] = { id = 31147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiger Palm", description = "As you overcome great challenges in your journey to master struggles both internal and external, you will begin to uncover new abilities hidden inside yourself. Go, now, and develop a mastery of yourself, such that you uncover the Tiger Palm technique. Then, go practice it on a training dummy.", sourceObjective = "Reach level 3 to learn Tiger Palm, then practice using it on a Training Dummy.", completion = "Ah, it's my favorite pupil! I'm going to go ahead to Undercity and try to teach the way of the {class} to some of the Deathguards. You should meet up with me there.", sourceObjectiveStatus = "unverified-source-field" }
quests[31148] = { id = 31148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Novice Elreth", description = "Actually, before I go - you should speak with Novice Elreth. She had some work for you, and you would do well to help others and improve your skills.\n\nThe next time you see me, I will be in Undercity.", sourceObjective = "Speak to Novice Elreth at Deathknell in Tirisfal Glades.", sourceObjectiveStatus = "unverified-source-field" }
quests[31150] = { id = 31150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elegant Rune", description = "{name}, this rune was given to me to pass on to ye. Take some time to read it when ye have a chance. I'm thinkin' it came from our visitor from afar, Lo. Take a gander at it and go find him inside Anvilmar.", sourceObjective = "Read the Elegant Rune and speak to Lo in Coldridge Valley.", progress = "I like it here, {name}. Your people have quite an appreciation for the finer things!", completion = "Well, it is good to see you. I must say, as much as you learn from me, I think I will learn from your people. Your brews are quite different than mine!", sourceObjectiveStatus = "unverified-source-field" }
quests[31151] = { id = 31151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kick, Punch, It's All in the Mind", description = "The truth is, you already have the talent and ability to learn what you need to. What I can help you do is show you where to unlock it.\n\nFirst, you must practice until you begin to understand a new technique. The first technique you learn will be the Tiger Palm. Go, learn more until you have unlocked the potential within yourself, and then practice your new move!\n\nRemember - it's all in the mind!", sourceObjective = "Reach level 3 to learn Tiger Palm, then use it on one of the Training Dummies outside the entrance to Anvilmar.", completion = "Ahh, good work. You may return any time you need another lesson from teacher.", sourceObjectiveStatus = "unverified-source-field" }
quests[31152] = { id = 31152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peering Into the Past", description = "Just a moment, now. Allow me to gather my things.\n\nWouldn't want me to lose these notes now, would we? Especially after you risked life and limb for them!\n\nThere, all set. Let us be off, shall we?\n\nI must say, I feel much safer traveling with you after seeing how you handled that saurok!", sourceObjective = "Speak to Lorewalker Cho at the Circle of Stone.", completion = "I am most grateful for the knowledge my forebears have passed on to me.\n\nI stand upon their shoulders.", sourceObjectiveStatus = "unverified-source-field" }
quests[31156] = { id = 31156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calligraphed Parchment", description = "Ah, while you were gone a parchment came for you, {name}.\n\nRead it when you have time. If I'm not mistaken, it came from our Pandaren friend, Gato. He visits from afar to grant us the honor of his wisdom, and to teach the ways of the monk. Do not shame your people by failing at his lessons!", sourceObjective = "Read the Calligraphed Parchment and speak with Gato in the Valley of Trials.", progress = "Ahh, you have come.", completion = "We will honor our respective peoples by learning from each other. You will become a great {class}, if I have anything to say about it. And I will learn the ways of your people.", sourceObjectiveStatus = "unverified-source-field" }
quests[31157] = { id = 31157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiger Palm", description = "As you walk the road of your training, you will begin to discover within yourself the power to unlock new techniques. You need not even learn them from me, or another more experienced monk - you will find that they come to you on their own.\n\nFor now, you should go and practice the basics. Gather more experience, and develop a new technique - once you have, you can practice it on the dummies nearby to master it.", sourceObjective = "Reach level 3 to learn Tiger Palm. Locate a Training Dummy and practice using Tiger Palm 2 times.", completion = "Good, good. Your first challenge surpassed. We will learn much from each other, I can see.", sourceObjectiveStatus = "unverified-source-field" }
quests[31158] = { id = 31158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Basics: Hitting Things", description = "Alright, mon. We start with da basics. I need ta know dat you know how ta swing dat weapon you're totin' around.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", sourceObjective = "Destroy 6 Tiki Targets.", completion = "Not bad, mon. Ya have a natural flow to ya punches - you may have a talent for dis.\n\nSome rough edges ta be sure, but we'll get dose ironed out here and I'll teach ya a few new tings as we go.", sourceObjectiveStatus = "unverified-source-field" }
quests[31159] = { id = 31159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Zabrax to the east.", sourceObjective = "Meet with Zabrax in the Darkspear Training Grounds.", completion = "Anotha newblood, eh?\n\nYa actually look ta be in shape though. Steady hands. Fierce eyes. I may be able ta turn ya into a real {class}.\n\nLets not waste anymore time 'den.", sourceObjectiveStatus = "unverified-source-field" }
quests[31160] = { id = 31160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", sourceObjective = "Retrieve 6 Wildmane Cat Pelts.", progress = "I doubt dey too much of a challenge, mon, but they'll still claw up ya ankles if ya don't stay quick footed.", completion = "Dese are some fine pelts, girl. We could make some hefty cloaks outta dese.", sourceObjectiveStatus = "unverified-source-field" }
quests[31161] = { id = 31161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", sourceObjective = "Speak to a Darkspear Jailor, then enter the proving pit and kill a Captive Spitescale Scout.", completion = "Ya handle yerself quite well. Ya gonna be quite powerful some day.", sourceObjectiveStatus = "unverified-source-field" }
quests[31162] = { id = 31162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arts of a Monk", description = "As ya get bettah' at fightin', you'll start to find new tings that ya nevah knew you could do.\n\nWanna see? Go, train up some, and learn someting new.\n\n'Den come back and ya can show me.", sourceObjective = "Reach level 3 to learn Tiger Palm. Practice using Tiger Palm against a Tiki Target.", completion = "Good work, mon! Dis stuff come easy to ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[31163] = { id = 31163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", sourceObjective = "Report to Vol'jin at Darkspear Hold.", completion = "Ya tha new recruit everyone's talkin' about, eh? Welcome ta tha Darkspear.", sourceObjectiveStatus = "unverified-source-field" }
quests[31165] = { id = 31165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calligraphed Note", description = "Just a moment ago a messenger was looking for you, {name}. I believe she was sent by our Pandaren visitor, Shoyu. You should read it.", sourceObjective = "Read the Calligraphed Note and speak to Shoyu in Camp Narache.", progress = "Ah, I am pleased to meet you.", completion = "I am honored that Chief Hawkwind would allow me to train you and grant you your rite of passage. While I am a master in the ways of the {class}, I am but a child in the ways of your people.", sourceObjectiveStatus = "unverified-source-field" }
quests[31166] = { id = 31166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiger Palm", description = "You have done well. As you continue along your path, you will grow, learning new techniques that you couldn't have imagined before.\n\nYour first lesson is the power of experience. Go, learn a new ability, and demonstrate it for me.", sourceObjective = "Reach level 3 to learn Tiger Palm. Locate a Training Dummy in Camp Narache and practice using it.", completion = "You have done well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[31167] = { id = 31167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Family Tree", description = "So there you have it, traveler, or as much of it as would make for a proper introduction, hmm?\n\nWhat of you, then? Are your people so much different than mine?\n\nSurely, there must be things we share in common. Let us see...", sourceObjective = "Light the Incense Bundle at the Circle of Stone.", progress = "A fine day we're having, wouldn't you say?", completion = "Not so different, you and I.\n\nI believe we can become good friends.", sourceObjectiveStatus = "unverified-source-field" }
quests[31168] = { id = 31168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calligraphed Sigil", description = "This sigil was given to me by a messenger from our Pandaren visitor, Laoxi. It seems he would have words with you when you have a moment. Read it and bring it to him afterwards.", sourceObjective = "Speak to Laoxi inside Aldrassil in Shadowglen.", progress = "Ah, you have come. Good.\n\nI am learning so much - your people have a wealth of knowledge unmatched anywhere I have seen. As much as I am humbled by that fact, I hope that I may teach you of our ways, as well.", completion = "I was warned that not all of your people would be welcoming, but I have found quite the opposite - not only have I been welcomed, but I have learned so much from you.\n\nYou seem quite promising as a young {class}, and I hope I can teach you much of our ways, as your people have taught me of yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[31169] = { id = 31169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of the Monk", description = "The true secret to the art of the monk is unlocking the knowledge and power hidden inside yourself.\n\nGo, get more experience, and learn a new skill. Then demonstrate it on one of the training dummies.", sourceObjective = "Reach level 3 to learn Tiger's Palm. Look for a Training Dummy and practice using Tiger's Palm.", completion = "You've proven a capable student. When it is time to resume your training, return to me and I will show you other techniques.", sourceObjectiveStatus = "unverified-source-field" }
quests[31170] = { id = 31170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monk Training", description = "As you advance within your class, you will want to take advantage of the training that your class trainer can provide you.  For young monks here on Sunstrider Isle, your trainer is Pao, our Pandaren visitor.  Speak with her and see what training she has available for you.\n\nPao - as with all the trainers on Sunstrider Isle - is inside the Sunspire on the lower level.", sourceObjective = "Speak with Pao, the Monk class trainer, inside the Sunspire on Sunstrider Isle.", completion = "Ah, welcome. I have been teaching your people the ways of the {class}, and they seem to be well suited for it. Perhaps you too will take to it as quickly as they.", sourceObjectiveStatus = "unverified-source-field" }
quests[31171] = { id = 31171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiger Palm", description = "Good. You are off to a bright start. This road will be long, and as you become more accomplished, you will begin to discover that you can do things you could never have imagined before.\n\nGo, get more experience, and learn a new technique. Once you have, demonstrate it on one of the training dummies.", sourceObjective = "Reach level 3 to learn Tiger Palm. Locate a Training Dummy outside the Sunspire and practice using it.", progress = "Have you practiced your Tiger Palm?", completion = "I think you've mastered the basics of the Tiger Palm technique, {name}. Perhaps you will impress me, after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[31172] = { id = 31172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monk Training" }
quests[31173] = { id = 31173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tiger Palm", description = "I hope your people are all alright... the crash was unbelievably loud and destructive!\n\n<Mojo looks you over, evaluating your potential.>\n\nYes, you'll do fine. They've said that they need more people to fight, and they don't want me to hurt myself. I'm not afraid, but I don't want to intrude. So, I'll teach you.\n\nAs you may have discovered, your experiences in combat will unlock new potential within you. Go, see if you can master a new ability. Show it to me. You'll get the hang of things.", sourceObjective = "Reach level 3 to learn Tiger Palm. Find a Training Dummy on the northwest side of the Crash Site and practice using it.", completion = "Keep that technique handy, {name}. You can use it to finish off strong opponents, or just to feel awesome, like a tiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[31175] = { id = 31175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skeer the Bloodseeker", description = "Our efforts to secure the shallows before Zan'vess have paid off.\n\nWe have spotted another paragon buried in amber, hidden in the waters to the southwest.\n\nAdding another paragon to our numbers is vital. Another champion from ages past could turn the tide in our favor.\n\nI would go immediately, but unfortunately, I am needed here.\n\nSince you are already a Wakener, you can carry out this task in my stead.", sourceObjective = "Awaken Skeer the Bloodseeker in the underwater cave.", completion = "The hunger... they said it would be fierce, but I did not expect anything like this.\n\nIt is strange to feel so... weak.", sourceObjectiveStatus = "unverified-source-field" }
quests[31176] = { id = 31176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Appetite", description = "Food. I must have food.\n\nIn my time, the meat of the starfish brought not only strength, but also clarity of mind. This is what I must eat.\n\nBring this to me from the nearby shallows.\n\nWait much longer, and I will devour you instead.", sourceObjective = "Collect 12 Starfish Meat.", progress = "The juices of the starfish will clear my mind.", completion = "Yes, give it here! Well done, Wakener.", sourceObjectiveStatus = "unverified-source-field" }
quests[31177] = { id = 31177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fine Dining", description = "In my living years, I was the greatest warrior of the swarm.\n\nHelp me regain my strength, and I shall show you.\n\nI smell the salt sea nearby, and where you can find the sea, you will find briny clackers.\n\nBring me their tails. I must feast upon their flesh.", sourceObjective = "Collect 8 Clacker Tails.", progress = "I have much work to do. The sooner I can fight, the sooner I can return to the Council.", completion = "Excellent. This shall give me the strength to vanquish my foes.", sourceObjectiveStatus = "unverified-source-field" }
quests[31178] = { id = 31178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bloody Delight", description = "A warrior is not ready for battle until he tastes the blood of his enemies.\n\nI am still too weak to hunt, so you must go in my stead.\n\nOnly the blood from the fiercest predators will do. I can smell their presence in the waters outside this cave!\n\nBring this to me, and then perhaps you shall see why they call me the Bloodseeker.", sourceObjective = "Collect 100 Volatile Blood from Dread Remoras.", progress = "By drinking the blood of your enemies, you acquire their strength.", completion = "Yes, this will do.", sourceObjectiveStatus = "unverified-source-field" }
quests[31179] = { id = 31179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scent of Blood", description = "I'm afraid that I wet my hands with saurok blood while you were away.\n\nI'm sorry, but I could not help myself. Now, watch them attack me.\n\nPitiful!\n\nDo they think to take vengeance for their fallen? Do they come challenge ME?\n\nI, who have won a hundred wars? I, who stood alone against thousands and still shouted for my enemies to come?\n\nNo, these... saurok... will crumple before me like paper before the flame!\n\nI shall show you my might, Wakener. Fight alongside me and see.\n\nHere they come!", sourceObjective = "Kill 12 Muckscale Flesheaters and the Muckscale Serpentus.", completion = "You have succeeded once again. Well done, Wakener.", sourceObjectiveStatus = "unverified-source-field" }
quests[31181] = { id = 31181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh Pots", description = "We got a load of empty crab pots out there that need fresh bait.\n\nNow, we COULD pull them one at a time and bait them up here in comfort. A nice chair to sit on, maybe a hot cup of tea to keep you warm. Sounds nice, doesn't it?\n\nNever gonna happen.\n\nHead to Lonesome Cove, immediately southwest, and bait those pots with two chunks of fresh sea monarch. By \"fresh\" I mean killed right there in the water.\n\nOh, and by \"pots\" I mean traps. If you wanna be part of the crew, you'd better learn the lingo.", sourceObjective = "Bait 10 Empty Crab Pots in Lonesome Cove. Each pot requires 2 Sea Monarch Chunks.", progress = "What's wrong, green? You aren't afraid of the dark, icy sea are you?", completion = "Not bad, green, not bad.", sourceObjectiveStatus = "unverified-source-field" }
quests[31182] = { id = 31182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Otter Know", description = "You know what happened to the bait in those pots?\n\nOtters. That's what happened.\n\nThey prefer fresh clams, but they'll pick our crab traps clean if they're hungry enough.\n\nThe otters in Lonesome Cove are protected by law and we run a legitimate operation here. As much as I'd love to chum those little rats and call it a day, we just make sure they aren't hungry enough to raid the crab pots.\n\nToss 'em a few clams to keep them busy while you're out there.", sourceObjective = "Use the Bag of Clams to feed 8 Coldwhisker Otters in Lonesome Cove.", completion = "That should keep their little whiskers out of our traps for awhile.", sourceObjectiveStatus = "unverified-source-field" }
quests[31183] = { id = 31183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the Cap'n", sourceObjective = "Speak with \"Soggy\" Su-Dao in Soggy's Gamble.", completion = "New deckhand, eh? We'll see about that.\n\nI run a tight ship - even if she IS at the bottom of the sea.", sourceObjectiveStatus = "unverified-source-field" }
quests[31185] = { id = 31185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walking Dog", description = "Dog ain't my \"pet.\" He's a member of this crew, and my best friend. Saved my life more than once, you know.\n\nBut I'm gettin' too old to walk him anymore, and he still needs his exercise. Take Dog for a trip around the shelf for me, would ya?\n\nHe loves to swim through the hot geysers just southeast of the shallows.\n\nHe absolutely has to... er... \"leave his mark\" on the dead whale at the far western edge of the shelf.\n\nOh, and he'll want to visit our old shipwreck, too. He likes to reminisce.", sourceObjective = "Take Dog to visit the hot geysers, the whale corpse, and the wreck of the Mist-Hopper on the Shelf of Mazu.", completion = "How did it go? I hope he didn't cause too much trouble!", sourceObjectiveStatus = "unverified-source-field" }
quests[31186] = { id = 31186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dog Food", description = "<Dog whines as best as a lion seal can, feebly lifting one flipper toward his massive jaws.\n\nHe's hungry.\n\nThe Shelf of Mazu is covered in rockshell makrura that should make a fine meal for him.>", sourceObjective = "Help Dog to eat the remains of 10 Rockshell Snapclaws.", progress = "<This has got to be the most pathetic lion seal you've ever seen.>", completion = "<Dog licks his chops happily, looking satisfied.>", sourceObjectiveStatus = "unverified-source-field" }
quests[31187] = { id = 31187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Crab", description = "I just got word that a string of pots we dropped this morning hit it BIG. We're on the crab!\n\nProblem is, the rips are getting stronger and we lost track of some of the pots. They're just sitting out there, filled with spiky blue GOLD!\n\nI need you back out there. Hook one of these buoys up to any of the full traps you find and send it to the surface for us.", sourceObjective = "Attach a Mist-Hopper Buoy to 8 Full Crab Pots on the Shelf of Mazu.", completion = "Nice work out there!", sourceObjectiveStatus = "unverified-source-field" }
quests[31188] = { id = 31188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shark Week", description = "Crabbing is our big money-maker, but we send all kinds of goods back around the wall. Oils, plants, even rare minerals - the sea's bounty is rich out here!\n\nRight now the big craze in the markets back home is thresher teeth. Apparently they make great necklaces?\n\nThreshers are all over the Shelf of Mazu to the west. Bring me lots of teeth!", sourceObjective = "Collect 200 Thresher Teeth by pulling them from the jaws of Longfin Threshers on the Shelf of Mazu.", progress = "Having actually seen someone eaten by a thresher, I'm not sure why you'd willingly string their teeth around your neck, but whatever.", completion = "Those are perfect, just put them down over there. I'd rather not touch them myself. Creeps me out.", sourceObjectiveStatus = "unverified-source-field" }
quests[31189] = { id = 31189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reeltime Strategy", description = "I never thought I'd see the day, but for the first time since... well, EVER, Master Angler Ju Lien asked for some help with his lines.\n\nApparently the sea is going crazy today and he can't keep up. See if you can give him a hand. He's fishing just south of here.", sourceObjective = "Assist Master Angler Ju Lien in Soggy's Gamble.", progress = "Go give Ju Lien a hand, would ya?", completion = "What happened out there?! I heard a scream and next thing I know these nasty things come rolling in on the next wave!", sourceObjectiveStatus = "unverified-source-field" }
quests[31190] = { id = 31190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mariner's Revenge", description = "I'm not gonna sit in a damn rocking chair while my crew gets devoured by a leviathan!\n\nCome on, let's get to the dock and launch a dinghy. I got a special one set up just for this kind of situation. My own little Mist-Hopper Jr.\n\nWe'll give that thing a case of harpoon fever.", sourceObjective = "Launch the Mist-Hopper Jr. from the dock in Soggy's Gamble and use it to bring down Jiao.", progress = "Let's go!", completion = "Nice shooting out there!\n\nI knew we could do it. Never met anything that can't be killed with enough harpoons.", sourceObjectiveStatus = "unverified-source-field" }
quests[31194] = { id = 31194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slitherscale Suppression", description = "The Slitherscale take orders from their leader, the Slitherscale Lizard-Lord. He can be found celebrating his victories on the southeastern corner of Windward Isle.\n\nIf we can destroy this leader, we can deal their tribe a great blow.\n\nWithout their lord, the Slitherscale will think twice before attacking the gentle cloud serpents of the east.", sourceObjective = "Kill the Slitherscale Lizard-Lord.", progress = "A snake without a head cannot strike.", completion = "Wonderful! I knew you could triumph against the Slitherscale lord.", sourceObjectiveStatus = "unverified-source-field" }
quests[31196] = { id = 31196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sra'vess Wetwork", description = "The mantid outnumber us quite badly. Hundreds of them for each of us.\n\nAnd, they surround us on two sides - at Gao-Ran in the south we're holding them off, but to the west, on the island they call Sra'vess, they continue to mass unabated.\n\nWe're not stupid. We're not going to launch a full scale attack on them. We can't sustain an intense battle on multiple fronts.\n\nInstead, we're going to send you, and one of our Wu Kao, to do some dirty work. Sounds fun, doesn't it?", sourceObjective = "Kill any 15 non-elite mantid near Sra'vess.", progress = "The mission isn't complete, {name}.", completion = "Good work. I think it's always best to strike while they're unprepared.", sourceObjectiveStatus = "unverified-source-field" }
quests[31197] = { id = 31197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bigger They Come...", description = "Killing the smaller mantid works mostly as a distraction. It forces them to replenish their numbers before they consider any serious offensive.\n\nThe big ones, though - we kill a few of those, and we really disrupt operations on the island. That buys ourselves a substantial amount of time. With mantid, it's like their size is directly proportional to their importance in the empire.\n\nSo kill some of the big ones for me, while you're out there.", sourceObjective = "Kill any 4 elite mantid at Sra'vess.", progress = "I don't think you're done yet.", completion = "Well done, well done. That should keep us safe for a few days, at least.", sourceObjectiveStatus = "unverified-source-field" }
quests[31198] = { id = 31198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Morale Victory", description = "The mantid have statues built on Sra'vess. We don't know exactly what they use them for. They may have some sort of religious significance, or maybe they assist with their sonic communication.\n\nWhen you fight your opponent, you don't just engage them physically, you also engage them mentally. Whatever they use them for, the fact is that those statues are important to them.\n\nWhich is why I want you to blow them up. Losing something important will be a substantial hit to morale.", sourceObjective = "Destroy the Southern, Central, Eastern and Western Idols at Sra'vess.", progress = "The statues?", completion = "I'm sure they'll be upset without those statues. Right?", sourceObjectiveStatus = "unverified-source-field" }
quests[31199] = { id = 31199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Siege Weapons!", description = "The mantid don't just attack in swarms. \n\nThey're smart. They use alchemy, bombs... and what's worst, they've got siege weapons. Those have the potential to be incredibly destructive if they attack with them.\n\nWe've got reports that they're building up a force of siege weapons to the west at Sra'vess. Go and destroy them.", sourceObjective = "Destroy the four mantid siege weapons at Sra'vess in Townlong Steppes.", progress = "You need to take out those siege weapons, {name}!", completion = "Those siege weapons won't be a problem. They may rebuild, but we've bought ourselves some time.", sourceObjectiveStatus = "unverified-source-field" }
quests[31200] = { id = 31200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fumigation", description = "Our alchemists have cooked up a set of gas bombs that will discourage mantid from staying anywhere that we set them off. \n\nIf we plant these in the critical structures of Sra'vess, they'll need to evacuate. That should sow some chaos and delay any action from the mantid there for days.\n\nGet to it, {name}.", sourceObjective = "Plant Shado-Pan Gas Bombs within the 5 targeted structures on Sra'vess.", progress = "Have you planted the gas bombs?", completion = "Nice, I can see the smoke from here. That should definitely cause some confusion!", sourceObjectiveStatus = "unverified-source-field" }
quests[31201] = { id = 31201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friends, Not Food!", description = "Our scouts have sent a very troubling report. \n\nThree of our trainees have gone missing, and our scouts found them... \n\nThey've been captured by the mantid and sent to their Kunchong pits. \n\nTheir Kunchong FEEDING pits. We're lucky that the Kunchong don't eat that often.\n\nI need you to get in there, give them these escape kites, and get them out!", sourceObjective = "Rescue a Shado-Pan Trainee in each of the north, central and south Kunchong feeding pits.", progress = "The trainees, {name}! You have to save them!", completion = "Oh, thank goodness. I was worried about them!", sourceObjectiveStatus = "unverified-source-field" }
quests[31203] = { id = 31203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target of Opportunity: Sra'thik Swarmlord", sourceObjective = "Kill the Sra'thik Swarmlord at Sra'vess in Townlong Steppes.", progress = "We need to take down the Swarmlord!", completion = "I heard you did a little... extra credit while you were out there. Good work, friend.\n\nCome back another day - I'm sure we'll have some more work for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[31204] = { id = 31204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Target of Opportunity: Sra'thik Hivelord", description = "Near the ocean, on the eastern side of Sra'vess, there is a cavern that leads to a network of caves.\n\nFrom there, the Sra'thik Hivelord maintains Sra'vess and plots against us. If we manage to take him out, we'll disrupt their operations for days.\n\nLet's go to it.", sourceObjective = "Defeat the Sra'thik Hivelord.", progress = "We've got to kill the Hivelord.", completion = "Well done, {name}! Because you took on that extra work, you've bought us some respite from the mantid.\n\nI'm sure I'll have more work for you in the future, though. Come back later.", sourceObjectiveStatus = "unverified-source-field" }
quests[31206] = { id = 31206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crucible of Carnage: The Bloodeye Bruiser!", description = "I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand or the bloodbowl in Zul'Drak, but hey, I go where the gold's at! So welcome to Twi-Hi, pal.\n\nYou're new to this pit, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match.\n\nIf you're ready and got a group of friends with you, we can start! What do you say?", sourceObjective = "Get in the arena at the Crucible of Carnage and defeat Hurp'derp!", sourceObjectiveStatus = "unverified-source-field" }
quests[31207] = { id = 31207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arena of Annihilation", description = "Ah, I can still remember running fights out of a muddy hole in the ground back in Nagrand. We've come a long way, eh, Wodin?\n\nI tell you, there's nothing more these Tiger monks like than a good scrap. So much so that they've paid good coin for me to set up shop here and help draw the strongest fighters from all around!\n\nSo how about it? You and a couple friends up for a few rounds in the Arena of Annihilation...? Big money, big prizes!", sourceObjective = "Enter and complete the Arena of Annihilation scenario. Afterwards, collect your reward from Wodin the Troll-Servant.", progress = "What are you waiting for? The monks are spoiling for a good show.", completion = "Gurgthock said you he'd make it worth your while, kid. Take your pick!", sourceObjectiveStatus = "unverified-source-field" }
quests[31208] = { id = 31208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venomous Intent", description = "If we are to strike against the Empress, we must arm ourselves with weapons. My own choice of weapon is of a particularly toxic design.\n\nThe scorpions wandering the ledge produce a deadly venom that they store in their tails.\n\nBring me their stingers, and I will show you how I earned the title of paragon.", sourceObjective = "Collect 8 Venomous Stingers.", progress = "Did you feel the venomtail's sting? Such lovely pain.", completion = "Well done, Wakener. I hope you handled these stingers carefully.\n\nThe natural poison from these scorpions is deadly, but slow.", sourceObjectiveStatus = "unverified-source-field" }
quests[31209] = { id = 31209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Wings, Dark Things", description = "I require another ingredient to create my first poison, Wakener.\n\nThis ingredient you can easily find on the scarabs nearby.\n\nKill them and bring me their wings.", sourceObjective = "Collect 150 Scarab Wings.", progress = "Scarab wings can be crushed to produce a very fine white, deadly powder.", completion = "Yes, excellent, Wakener! These are perfect.\n\nHave you ever considered learning the poisoner's craft?", sourceObjectiveStatus = "unverified-source-field" }
quests[31210] = { id = 31210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shade of Dread", description = "The last ingredient is perhaps the deadliest.\n\nThe dreadshade flower grows all along these hills.\n\nIt is by eating these poisonous plants that the local wildlife has become so venomous.\n\nA single drop of dreadshade nectar can stop a kunchong's heart.\n\nGo and bring me some of these flowers. Do not be tempted to taste them.", sourceObjective = "Collect 8 Dreadshade.", progress = "Sometimes, the most beautiful things are also the most dangerous.", completion = "Many would not know the value of what you hold.\n\nYou have done well, Wakener.", sourceObjectiveStatus = "unverified-source-field" }
quests[31211] = { id = 31211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Poisoned Mind", description = "Before we return to Klaxxi'vess, I wish to look upon the empire.\n\nThe Klaxxi Council told me that the enemy gathers outside the Empress's palace.\n\nMy poisons are ready. What better way to announce my return than with death and destruction?\n\nJust be careful not to mix the two serums... at least not while you're holding the vessels.\n\nSpeak to me when you are ready to fly.", sourceObjective = "Speak to Xaril the Poisoned Mind. Kill 200 mantid and 3 kunchong while flying with him.", progress = "Fight from above.", completion = "Thank you for returning me home, Wakener, but I fear the war has just truly begun.", sourceObjectiveStatus = "unverified-source-field" }
quests[31216] = { id = 31216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Skies", description = "The swarm begins, Wakener! The mantid amass at the Heart of Fear.\n\nAlready they fill the skies with their wings and rend the earth with their claws. They shall not stop the dark march until their bodies are laid open and bleeding upon the ground.\n\nThis we shall gladly do. We will attack them from above. While I fly, use my poisons to destroy their advance.\n\nDo not mix the two serums until you are ready to attack. The reaction can be quite... violent.\n\nSpeak to me when you are ready to go.", sourceObjective = "Kill 200 Mantid and 3 Kunchong or Dread Behemoths while flying with Xaril the Poisoned Mind.", progress = "Such wonderful destruction!", completion = "Well done, Wakener. You have a destroyer's aim.", sourceObjectiveStatus = "unverified-source-field" }
quests[31220] = { id = 31220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenger's Ring: Hawkmaster Nurong", description = "You've really been building up respect with the Shado-Pan, {name}.\n\nNurong's interested in trying out his skills against you.\n\nThe good news is, if you win, I'll allow him to go with you on your missions.\n\nThe bad news is, I really don't think you'll win.", sourceObjective = "Challenge Hawkmaster Nurong, and then defeat him in combat at Shado-Pan Garrison in Townlong Steppes.", progress = "Not up to the challenge? I understand.", completion = "Well, well, well. Looks like I was wrong.\n\nGood work. Nurong's looking forward to accompanying you on your missions.", sourceObjectiveStatus = "unverified-source-field" }
quests[31221] = { id = 31221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenger's Ring: Tenwu of the Red Smoke", description = "So... you've been challenged by the infamous Tenwu of the Red Smoke.\n\nThat's what he calls himself, at least. He's a good fighter, and a good rogue, but it's a wonder he manages to sneak up on anyone with how loudly he brags about himself.\n\nAnyways, I think you should answer the challenge. Maybe it'll give him a touch of humility. Maybe not. Either way, if you win, he'll probably be willing to go with you on your missions. \n\nAnd I get some entertainment.", sourceObjective = "Challenge Tenwu of the Red Smoke, and then defeat him in combat at Shado-Pan Garrison in Townlong Steppes.", progress = "Well? How did it go?", completion = "Wow! Well done. Glad to see you fought so well.\n\nMaybe if he's trying to keep up with your fighting it'll help keep his mouth shut.", sourceObjectiveStatus = "unverified-source-field" }
quests[31228] = { id = 31228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prophet Khar'zul", description = "Prophet Khar'zul is a powerful caster, but he is also underestimating your abilities.\n\nKhar'zul and his forces must be destroyed to protect this village. His death will send a strong message to the Thunder King that we will not be defeated!\n\nYou'll find him on the Isle of Reckoning.", sourceObjective = "Defeat Prophet Kharzul.", progress = "Is Khar'zul dead?", completion = "These events should be learned from, {name}.\n\nIt is important that we learn from our history. Had we paid attention to the histories, we may have been able to head this off before it got this far.\n\nEverything that has happened was already foretold, we just didn't know how to read it.", sourceObjectiveStatus = "unverified-source-field" }
quests[31230] = { id = 31230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Dawn's Blossom", description = "Cho's off on another one of his adventures, and this one requires a big order of jade. I'm going to have to call in some favors.\n\nHow 'bout in the meantime you introduce yourself to some of the locals.\n\nKai Wanderbrew is a good guy to know, as is Master Windfur. Oh, and say hi to Peiji Goldendraft up at the inn.\n\nBetween the three of them, you should get the feel for life in Dawn's Blossom.", sourceObjective = "Speak with Kai Wanderbrew, Master Windfur, and Peiji Goldendraft in Dawn's Blossom.", progress = "Any luck?", completion = "Good, good, good. You're going to fit right in.", sourceObjectiveStatus = "unverified-source-field" }
quests[31231] = { id = 31231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadspinner Extermination", description = "Back in Gurthani Terrace where you found me, dreadspinners continue to occupy the attention of Shado-Pan marksmen who could otherwise be thinning out this wretched swarm.\n\nEradicate those spiders and offer some relief to the archers on that wall.", sourceObjective = "Slay 8 Dreadspinner Tenders in the Terrace of Gurthan. Speak with Kil'ruk the Wind-Reaver for an air-drop.", completion = "I never liked spiders. Filthy, mindless insects.", sourceObjectiveStatus = "unverified-source-field" }
quests[31232] = { id = 31232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Empire", description = "My brothers speak of an ancient mogu empire that once dwelled in the ruins to the east.\n\nOnce, this tribe knew untold secrets of sorcery and subjugation.\n\nI have a curious mind, Wakener, and I wish to learn of the empires that ruled after my time.\n\nKnowledge of the past will determine our future.\n\nGo search the ruins for their ancient tablets. I will study their secrets and make them our own.", sourceObjective = "Collect 8 Gurthani Tablets.", progress = "What knowledge do you bring?", completion = "Good, Wakener. It will take me time to decipher these tablets, but all knowledge is worthy.", sourceObjectiveStatus = "unverified-source-field" }
quests[31233] = { id = 31233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sap Tapping", description = "I found a grove of young amber trees to the east, Wakener.\n\nI've placed tapping devices on these trees, but I have been too busy to retrieve the sap.\n\nI need someone to find the extractors. Activate them, then bring me samples of the amber.", sourceObjective = "Collect 6 Amber Sap.", progress = "These trees are still young. They are not yet kypari.\n\nTheir sap is like water, while the sap of a true kypari tree is like wine.\n\nThey must be allowed to grow.", completion = "Ah yes, this is exactly what I needed.\n\nI will examine these samples. We must continue to monitor the health of these young kypari.", sourceObjectiveStatus = "unverified-source-field" }
quests[31234] = { id = 31234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting An Eye Out", description = "Ah! Wakener! You must help me! (You will help me, or else I will help myself to you!)\n\nI need more materials for my experiments, yes yes! (Blood and guts, hearts and brains, tongues and eyes, eyes, eyes!)\n\nTo the west, I have seen creatures of mist and fog. They possess such big, round, wonderful globes! Big for seeing, round and unblinking!\n\nGo now, little Wakener. Bring me back a single pristine eye!", sourceObjective = "Collect 1 Pristine Mire Beast Eye.", progress = "Ooooh, what wonderful, tasty parts have you brought me?", completion = "Yes, yes! Wonderful! Oh, so delicious!", sourceObjectiveStatus = "unverified-source-field" }
quests[31235] = { id = 31235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nope Nope Nope", description = "I recovered this weapon on a recent scouting run near the wall. It would seem ideal for helping your Shado-Pan with their infestation problem in Gurthani Terrace.\n\nThe more they are focused on keeping spiders off the wall, the less time they are killing fear-gripped swarmborn.", sourceObjective = "Use the Shado-Pan Dragon Gun to destroy 20 Dreadspinner Eggs in Gurthani Terrace.", completion = "A crude weapon, but it has its uses.", sourceObjectiveStatus = "unverified-source-field" }
quests[31237] = { id = 31237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Debugging the Terrace", description = "If this Empress is truly possessed by fear and paranoia, she will have sent scouts to every corner of the land in order to cement her control.\n\nThese scout grubs are likely everywhere, but difficult to spot with the naked eye. Better to track them by the pheromone trails they leave behind.\n\nI've already... gifted you... a reactive toxin that will reveal these trails to you for a brief time after experiencing the thrill of victory.\n\nGo now to the Terrace of Gurthan and root out these spies.", sourceObjective = "Stomp out 6 Eyes of the Empress around the Terrace of Gurthan. Killing anything will grant you Pheromone Tracking, helping you detect them.", progress = "Best not to ask how I afflicted you with the toxin - you have become quite useful to us, and it would be a shame if we drove you mad with horror just yet.", completion = "Information is power, {name}. We cannot allow the Empess to monitor our movements.", sourceObjectiveStatus = "unverified-source-field" }
quests[31238] = { id = 31238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brain Food", description = "Kovok is growing at an accelerated rate, but his brain may not be able to keep up. He'll require a special diet to ensure that he does not outgrow the capacity to control his own body.\n\nMushan tongue is rich in the nutrients that promote brain growth in kunchong, but they normally eat the beasts whole and fill up quickly. If we feed Kovok only mushan tongues every couple of days or so, it should balance out his growth.\n\nGreatback mushan graze the hills east of here, near the Gurthani Terrace.", sourceObjective = "Bring 4 Mushan Tongues to Kaz'tik the Manipulator at Klaxxi'vess.", progress = "Have you found a suitable meal for Kovok?", completion = "Kovok was whining the whole time you were away. It was really quite pathetic.", sourceObjectiveStatus = "unverified-source-field" }
quests[31239] = { id = 31239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's in a Name Name?", description = "So, you wanna be a hozen. Huh, wikket?\n\nHozen defend their lands from enemies, like jinyu.\n\nKah Kah fought many jinyu fights, and won them all.\n\nHozen only give name name to good grookers. Go grook jinyu and maybe they call you {name} {name}.\n\nJinyu creepin' down by the river. Ook 'em in the dooker!", sourceObjective = "Kill 7 Riverstride Jinyu", completion = "Ha ha! Wikket Grooked ookin' Jinyu!", sourceObjectiveStatus = "unverified-source-field" }
quests[31240] = { id = 31240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guo-Lai Infestation", description = "Anji came by and asked for you. Said she was heading to the northeast ruins.\n\nOh, Anji, such a fiery spirit, that girl! Probably better for your long-term health if you not keep her waiting.", sourceObjective = "Speak to Anji Autumnlight at the Ruins of Guo-Lai.", completion = "Good, you're here.\n\nFor a while there, I was wondering if Ren would even deliver the message.", sourceObjectiveStatus = "unverified-source-field" }
quests[31241] = { id = 31241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wicked Wikkets", description = "{name} good wikket, they say...\n\n{name} help hozen, they say...\n\nNo more grookin' {name}, they say.\n\nThat ok. Look out there. Wicked wikkets fallin' like rain, ripe for the grookin'!\n\nGo, join the fun. But remember, Chief Kah Kah gets all the shinies! That's hozen rule number two.\n\n<Jeek Jeek scratches his head.>\n\nHmm, all hozen rules are number two...", sourceObjective = "Collect 6 Alliance Service Medallions from Battleworn Paratroopers", progress = "Whatcha got, wikket?", completion = "Wikket grookin' makin' hozen rich with shinies!\n\n{name} makin' a good second impression. And for hozen, number two is most important!", sourceObjectiveStatus = "unverified-source-field" }
quests[31242] = { id = 31242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistfall Village", description = "My scouts have spotted no mogu near Mistfall Village today, but I've been hearing of some troubles with local wildlife and spirits in the graveyard. I dispatched Che to assess the situation, but he'll most likely need your help.\n\nFind your way southwest to the village and meet Che there. Do what you can.", sourceObjective = "Speak to Che Wildwalker at Mistfall Village.", completion = "Leven sent me a good one today! I must thank him later.", sourceObjectiveStatus = "unverified-source-field" }
quests[31243] = { id = 31243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Mistfall Village", description = "Mogu have been sighted at Mistfall Village to the southwest. I dispatched Rook and Sun immediately, but I need another capable hand there as soon as possible.\n\nDon't delay. The villagers need you.", sourceObjective = "Speak to Sun Tenderheart at Mistfall Village.", completion = "Oh, thank the celestials you're here! This is worse than we thought!", sourceObjectiveStatus = "unverified-source-field" }
quests[31244] = { id = 31244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guo-Lai Encampment", description = "Leven came by in quite a huff! Said something about mogu in the ruins.\n\nBest be off to find him I think. Angry Leven is not a fun Leven.", sourceObjective = "Speak to Leven Dawnblade at the Ruins of Guo-Lai.", sourceObjectiveStatus = "unverified-source-field" }
quests[31245] = { id = 31245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistfall Village", description = "Che stopped by on the way to the village and ask if I'd seen you. I told him no.\n\nYou can go see him if you want. But now you're not obligated to see him! I am so marvelously considerate, am I not?", sourceObjective = "Speak to Che Wildwalker at Mistfall Village.", completion = "Ren send you my way? He puts on playful air, but he follows through when it matters. Can't hold it against him much.", sourceObjectiveStatus = "unverified-source-field" }
quests[31246] = { id = 31246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Mistfall Village", description = "I can see smoke from the village. And it's not my fault this time!\n\nBest go and help.", sourceObjective = "Speak to Rook Stonetoe at Mistfall Village.", completion = "You come to help Rook?", sourceObjectiveStatus = "unverified-source-field" }
quests[31247] = { id = 31247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting Sun Garrison", description = "Anji and Kun stopped by on the way to the garrison. Lovely pair, don't you think? So different, yet so devoted to each other... ah, it makes my heart swoon just thinking about it.\n\nThey asked for you by name. Maybe they want to put you through some of the training paces? I certainly hope they don't have something more naughty in mind...", sourceObjective = "Speak to Anji Autumnlight at the Setting Sun Garrison.", completion = "Well timed. I was just about to go put some recruits through their paces, but I'd be much more eager to see what you have to offer.", sourceObjectiveStatus = "unverified-source-field" }
quests[31248] = { id = 31248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Guo-Lai", description = "I've instructed Anji and Kun to resume investigation of the Ruins of Guo-Lai. We have no reports of any significant mogu presence there today, but it seems to be one of their central interests here in the Vale, and want it under thorough watch consider their attack on the lake.\n\nThat's why I'm sending you as well.\n\nHead west, past the lake, to the ruins. Anji will instruct you further.", sourceObjective = "Speak to Anji Autumnlight at the Ruins of Guo-Lai.", completion = "If it isn't one of my favorite shamans. Glad to have you with us.", sourceObjectiveStatus = "unverified-source-field" }
quests[31249] = { id = 31249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistfall Village", description = "Everything I've heard suggests the village has been unaffected by the Shao-Tien offensive at the lake, but I won't take any risks.\n\nI'm dispatching you and Che Wildwalker to keep watch at the village, and aid the townsfolk while you're there.", sourceObjective = "Speak to Che Wildwalker at Mistfall Village.", completion = "It is strange to be dispatched away from the combat, but Leven is right in that the villagers need our protection. We cannot afford any risks.", sourceObjectiveStatus = "unverified-source-field" }
quests[31250] = { id = 31250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting Sun Garrison", description = "We've taken losses from the mogu forces descending the Golden Stair and their flanking attackers at Whitepetal Lake. Our lines are thin.\n\nI'm dispatching Anji and Kun to the Setting Sun Garrison to double our efforts at training new recruits. I'd like you there with them, {name}. Show them what a true {class} is made of.", sourceObjective = "Speak to Anji Autumnlight at the Setting Sun Garrison.", completion = "Let's whip these recruits into shape.", sourceObjectiveStatus = "unverified-source-field" }
quests[31251] = { id = 31251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Best Meals Anywhere!", description = "Yeah, yeah.\n\nEveryone knows us goblins do tinkering. And explosives. And... well, ya' know, the less reputable stuff.\n\nBut what nobody knows is that I'm really a great chef! It's a hobby of mine.\n\nGather us up some meaty bits from the creatures around here, and I'll cook us up the best meals ANYWHERE!\n\nAnd I promise, I'll only use three or four percent rocket fuel.", sourceObjective = "Collect 160 Kun-Lai Meaty Bits.", progress = "The meaty bits, {name}? We need 'em!", completion = "You know what they say about cooking - GTL. Garnish, taste... and... laundry?", sourceObjectiveStatus = "unverified-source-field" }
quests[31252] = { id = 31252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Westwind Rest", description = "Well, far as I figure, we've got quite a lot of rebuildin' to do.\n\nI'm not one for joining any big causes, but my farmhands aren't gonna have much to do 'round here, to be honest. And, since you helped them out, they want to join your \"Alliance.\" So, who am I to stop 'em?\n\nBring 'em with you, back to Farmhand Bo. I'll miss 'em, but they're better off with you.", sourceObjective = "Return to Farmhand Bo at Westwind Rest in Kun-Lai Summit.", completion = "You did good, bringing these guys back. We'll have 'em farming you up some food in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[31253] = { id = 31253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Eastwind Rest", description = "Well, far as I figure, we've got quite a lot of rebuildin' to do.\n\nI'm not one for joining any big causes, but my farmhands aren't gonna have much to do 'round here, to be honest. And, since you helped them out, they want to join your \"Horde\". So, who am I to stop 'em?\n\nBring 'em with you, back to Farmhand Ko. I'll miss 'em, but they're better off with you.", sourceObjective = "Return to Farmhand Ko at Eastwind Rest in Kun-Lai Summit.", completion = "You did good, bringing these guys back. We'll have 'em farming you up some food in no time!", sourceObjectiveStatus = "unverified-source-field" }
quests[31254] = { id = 31254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to Kun-Lai", description = "Ah! Greetings friend of Lorewalker Cho. I have a message for you.\n\n<The strange little creature hands you a battered scroll case.>\n\nThe Lorewalker waits for you in Kun-Lai. Very dangerous to travel there, yes, very dangerous.\n\nLook for guides along the road to help you find your way.", sourceObjective = "Travel through the Veiled Stair to Binan Village.", progress = "More strangers? This day is testing my limits.", completion = "Oh, you are a friend of Cho's? Welcome! Welcome!\n\nI would serve you a banquet but as you can see we are in dire straights at the moment.\n\nSay, would you be willing to lend us a hand?", sourceObjectiveStatus = "unverified-source-field" }
quests[31255] = { id = 31255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to Kun-Lai", description = "Ah! Greetings friend of Lorewalker Cho. I have a message for you.\n\n<The strange little creature hands you a battered scroll case.>\n\nThe Lorewalker waits for you in Kun-Lai. Very dangerous to travel there, yes, very dangerous.\n\nLook for guides along the road to help you find your way.", sourceObjective = "Travel through the Veiled Stair to Binan Village.", progress = "More strangers? This day is testing my limits.", completion = "Oh, you are a friend of Cho's? Welcome! Welcome!\n\nI would serve you a banquet, but as you can see, we are in dire straights at the moment.\n\nSay, would you be willing to lend us a hand?", sourceObjectiveStatus = "unverified-source-field" }
quests[31256] = { id = 31256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 'Em Up", description = "Lok'tar, {class}.\n\nWe've made progress, but we're going to need mobility if we want to maintain our foothold here in Kun-Lai.\n\nI don't see many worgs, kodo, or the like around here. What I do see are yaks. Our pandaren allies have said they make good mounts, so they'll have to do.\n\nGo round some up and return them here, so we can get our people riding them!", sourceObjective = "Round up 3 Wild Plains Yaks and return them to Eastwind Rest.", progress = "The yaks?", completion = "Well done! Well, they're plenty stubborn, I'll say that much. But they should do nicely.", sourceObjectiveStatus = "unverified-source-field" }
quests[31260] = { id = 31260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profit Mastery: Chasheen", description = "I am totally on to another great scam!\n\nWhen I was flying overhead I saw a really ancient tigress prowling about.\n\nDo you know how much her blood would go for on the black market? Not to mention if I convince some warlocks it adds extra potency to their summoning spells or something.\n\nIf you bring me back some of her blood I will cut you in on the scam. She was prowling about on the far side of the Dojani River from here.", sourceObjective = "Collect Ancient Tiger's Blood.", progress = "I thought about taking that tiger on myself but to be honest I like living...", completion = "Impressive! Can you smell the money? Here's your end.", sourceObjectiveStatus = "unverified-source-field" }
quests[31261] = { id = 31261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Jack's Dead", description = "Gore from Captain Jack's head drips and mysteriously seeps into the ground as you examine your hard-won trophy.\n\nStrange, but no time to investigate that now. There's too much work to be done.\n\nThe chieftain of your newfound friends will doubtlessly be impressed with this proof of your grookin' skills.", sourceObjective = "Bring Captain Jack's head to Chief Kah Kah at Grookin Hill.\n\nProvided item:", completion = "Ookin' grookin, wikket!", sourceObjectiveStatus = "unverified-source-field" }
quests[31262] = { id = 31262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crane Mastery: Needlebeak", description = "So, now that you've got a vibe for how cranes fight, I've got a doozy for you.\n\nNeedlebeak!\n\nOr at least, that's what I'm calling him. Biggest crane I ever saw. And its beak is so sharp it's like a sword.\n\nNorthwest of here you'll find the big water fall that kicks off the Dojani River. Needlebeak likes to hang out by the waterfall.\n\nYou bring me its beak as a trophy and I will talk you up a good game to Nesingwary.", sourceObjective = "Acquire the Needlebeak.", progress = "I watched that bird stab a tiger through the face. What kind of place is this where birds are the predators for tigers?", completion = "Now THAT is a trophy. Looks intimidating. Wait... is this your blood on it?", sourceObjectiveStatus = "unverified-source-field" }
quests[31265] = { id = 31265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mazu's Breath", description = "Here to help, are ya? Well, first thing's first.\n\n<Arie rummages through her pockets for a moment before producing a small vial of glowing blue fluid.>\n\nHere it is! \"Mazu's Breath.\" Cap'n's own formula.\n\nWhat? You thought I'd send you out to sea without a means of breathin'? I need deckhands, not corpses!\n\nDown the hatch with it, green. This'll give you a fighting chance out there on the shelf.", sourceObjective = "Drink the Potion of Mazu's Breath.", progress = "No, I don't have a \"chaser!\" Just drink it!", completion = "You'll thank me later.", sourceObjectiveStatus = "unverified-source-field" }
quests[31266] = { id = 31266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu Incursions", description = "We've heard reports of a group of Mogu infiltrating the coast here in Townlong. I have no idea what they are doing. Frankly, I don't care. \n\nYou've proven yourself, so we've decided to give this mission to you.\n\nWhat's going to happen is this - you're going to go, find them, and kill them.\n\nOur scouts reported the first group landed to the north, between here and Deadtalker's Plateau. Go there and wipe them out.", sourceObjective = "Find and kill the Shan'ze Spymaster.", progress = "Why aren't they dead already?", completion = "It was just a decoy! They've moved to attack Niuzao Temple!", sourceObjectiveStatus = "unverified-source-field" }
quests[31267] = { id = 31267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistblade Destruction", description = "Korven has told me of his findings. There is an enormous amber deposit sitting at the bottom of the Lake of Stars.\n\nUnfortunately, a hostile saurok tribe lives at the edge of the lake, and revere the amber as their own.\n\nThey will not allow us to enter their territory easily.\n\nGo south to the lake. Kill the Mistblade saurok, so that we can more easily harvest the nearby amber.", sourceObjective = "Kill 6 Mistblade Rippers.", progress = "Have you eliminated the opposition?", completion = "Well done. With access to this amber, we shall be able to craft weapons to our cause.", sourceObjectiveStatus = "unverified-source-field" }
quests[31268] = { id = 31268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Brain Work", description = "Far to the south, the swarm breeds weapons of destruction - enormous, nearly unbreakable amber scorpions.\n\nLike all other creatures, they are subject to manipulation, but unlike other creatures, they have not yet submitted to my mind control.\n\nIt appears that further research is necessary before I can dominate them for our own purposes.\n\nI must study their brains, and you must retrieve some specimens for me.\n\nTake this sonic emitter. I have found it to be quite effective against the beasts.", sourceObjective = "Collect 3 Amber-Encrusted Brains from Ik'thik Amberstingers.", progress = "They continue to resist my sonic manipulation. I must understand why.", completion = "My my, this is interesting indeed. They are unlike any other brains I have seen.\n\nI will study these carefully.", sourceObjectiveStatus = "unverified-source-field" }
quests[31269] = { id = 31269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scale-Lord", description = "The saurok at the Lake of Stars take their orders from their Scale-Lord, a vicious, merciless leader who guards his territory fiercely.\n\nIf we can eliminate this leader, then we can gain access to the enormous amber lode beneath the lake.\n\nGo. Their leader gives his orders from his underground dwelling, at the southern edge of the lake.", sourceObjective = "Kill the Mistblade Scale-Lord.", completion = "Good. I am glad to hear that he is dead.", sourceObjectiveStatus = "unverified-source-field" }
quests[31270] = { id = 31270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fight Against Fear", description = "When we discovered the sha influence at Kypari Zar, I had hoped the corruption could still be cleansed.\n\nUnfortunately, the Klaxxi Council has confirmed that the sha of fear's corruption is deep-seated, and continues to spread.\n\nTo the south, I have observed some of the local wildlife consumed by an unnamed terror.\n\nThe sha can warp and twist its victims into unimaginable horrors.\n\nWe must stop the corruption before it becomes worse. Seek out the sha-infected Horrorscale Scorpids. Eliminate them.", sourceObjective = "Kill 15 Horrorscale Scorpid.", completion = "You have purged the hills of the infected creatures? Good.\n\nThe sha is a merciless enemy. Thus must we be merciless in return.", sourceObjectiveStatus = "unverified-source-field" }
quests[31271] = { id = 31271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Genes", description = "Far to the south, Wakener, the Empress's genemancers set about their dark experiments. (Dark yes, but not as dark as mine!)\n\nThey dissect and mutate the nearby wildlife, breeding creatures of their own design. (Their design, which will become my design!)\n\nWe must not let them succeed! (No, no! Only I am allowed such power!)\n\nTheir mutations are already being unleashed for war. Go! Destroy them at any cost!", sourceObjective = "Kill 3 Ik'thik Genemancers and 6 Ik'thik Egg-Drones.", progress = "Is it done? Are my competitio - I mean, our enemies - dead?", completion = "Yes, yes! They are dead!\n\nThank you, Wakener. Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[31272] = { id = 31272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infection", description = "The Empress's genemancers play with dangerous toys.\n\nTo the south, they are injecting local wildlife with pheromone-laden parasites, in an attempt to create monstrous mutations for war.\n\nCarelessly, they have allowed their parasitic worms to escape into the local ecosystem.\n\nLeft unchecked, the infection will spread from one animal to another, until we have an outbreak.\n\nI will inject you with a mild toxin. With it, you will be able to identify infected creatures.\n\nKill the carriers at once.", sourceObjective = "Kill 6 infected wildlife. Infected wildlife may include Bonedust Moths, Bluehide Mushan, and Mutating Scorpid.", progress = "Do not worry. I have given you a weak toxin that allows you to share my ability to sense pheromones.\n\nIt has no effect on mantid.", completion = "So the infection was spreading. You halted the spread just in time, it seems.\n\nI doubt that the genemancers will stop their outrageous experimentation, but we must continue to thwart their efforts.", sourceObjectiveStatus = "unverified-source-field" }
